// External diagnostic control only. Exact complete52f source; no semantic overlay.
import java.security.MessageDigest
import groovy.json.JsonSlurper
final File prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/normal-star-flow-admission-history-audit-20261106/same-program-52f-control')
final File historicalRoot = new File(prep, 'source').canonicalFile
final File forbiddenCurrentRoot = new File('/drive-testcomp/opentaint-go-rules/opentaint-w3').canonicalFile
final def parse = { String file -> new JsonSlurper().parse(new File(prep, file)) }
final def sha = { File file ->
    def md = MessageDigest.getInstance('SHA-256')
    file.withInputStream { stream -> byte[] buf = new byte[65536]; int n
        while ((n = stream.read(buf)) > 0) md.update(buf, 0, n)
    }
    md.digest().encodeHex().toString()
}
final def sourcePins = parse('source-tree-pins.json')
final def manifest = parse('prepared-manifest.json')
final def provider = parse('provider-pins.json')
final def verify = {
    if (sourcePins.revision != '52f32dd437d438aec4a700a02c18d94c31d58093' || sourcePins.count != 5279)
        throw new GradleException('Wrong historical source revision/count')
    for (pin in manifest.preparedInputs) {
        def f = new File(prep, pin.path)
        if (!f.isFile() || f.length() != pin.bytes || sha(f) != pin.sha256)
            throw new GradleException('Prepared control changed: ' + f)
    }
    for (pin in sourcePins.files) {
        def f = new File(historicalRoot, pin.path)
        if (!f.isFile() || f.length() != pin.bytes || sha(f) != pin.sha256)
            throw new GradleException('Historical source changed: ' + f)
    }
}
verify()
allprojects { p ->
    if (p.name == 'opentaint-dataflow' && p.projectDir.name == 'opentaint-dataflow') {
        p.afterEvaluate {
            def expected = new File(historicalRoot, 'core/opentaint-dataflow-core/opentaint-dataflow').canonicalFile
            if (p.projectDir.canonicalFile != expected) throw new GradleException('Not the complete historical build')
            def ss = p.sourceSets.create('historical52fLoopBoundaryReproducer')
            ss.java.setSrcDirs([]); ss.resources.setSrcDirs([])
            p.kotlin.sourceSets.getByName(ss.name).kotlin.setSrcDirs([new File(prep, 'harness/src')])
            ss.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
            def classes = p.layout.buildDirectory.dir('classes/kotlin/historical52fLoopBoundaryReproducer')
            ss.output.classesDirs.setFrom(classes)
            p.tasks.named('compileHistorical52fLoopBoundaryReproducerKotlin') {
                dependsOn p.tasks.named('testClasses')
                destinationDirectory.set(classes)
                compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
                compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
                    p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
                    p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile
                ].collect { it.absolutePath }.join(','))
                doFirst { verify() }
            }
            p.tasks.register('runHistorical52fLoopBoundaryPrecisionReproducer', JavaExec) {
                dependsOn p.tasks.named('compileHistorical52fLoopBoundaryReproducerKotlin')
                classpath = ss.output + p.sourceSets.test.runtimeClasspath + p.files(provider.jars.collect { new File(it.path) })
                mainClass.set('org.opentaint.dataflow.bidi.LoopBoundaryPrecisionReproducer')
                jvmArgs '-Xmx1g', '-XX:ActiveProcessorCount=1'
                timeout.set(java.time.Duration.ofSeconds(20))
                systemProperty 'logback.configurationFile', new File(prep, 'logback.xml').absolutePath
                doFirst {
                    verify()
                    if (classpath.files.iterator().next().canonicalFile != classes.get().asFile.canonicalFile)
                        throw new GradleException('Fresh historical harness must lead classpath')
                    if (classpath.files.any { it.canonicalPath.startsWith(forbiddenCurrentRoot.path + File.separator) })
                        throw new GradleException('Current worktree entry on historical classpath')
                    new File(prep, 'actual-classpath.txt').text = classpath.files.collect { it.absolutePath }.join('\n') + '\n'
                    println('HISTORICAL52F_REVISION=' + sourcePins.revision)
                    println('HISTORICAL52F_EXPECTED_APOPS=' + p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile)
                    println('HISTORICAL52F_JVM_ARGS=' + jvmArgs)
                }
            }
        }
    }
}

