package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.SoftReferenceManager

/** FLOW values for one base, separated by layer and both exclusions. One store writer owns this group. */
class FlowGroup(private val m: ApManager, private val interner: TrieInterner<FlowLeaf>) {
    private val trees = arrayOf(ArrayList<FlowTree>(1), ArrayList<FlowTree>(1))

    fun all(): Sequence<FlowTree> = trees[0].asSequence() + trees[1].asSequence()

    /** T4: return the new part, or the merged value when T2 changes an annotation. */
    fun add(t: FlowTree): FlowTree? = addAll(t).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(t: FlowTree): List<FlowTree> {
        m.cancellation.checkpoint()
        val before = trees[t.layer.ordinal]
        if (t.tail != Tail.ANY && t.tail != Tail.ANY_TAINT)
            return addInto(t,before)?.let(::listOf) ?: emptyList()
        if (before.isEmpty()) {
            val canonical = m.canonicalFlowPacket(t)
            val root = interner.internIfRequired(canonical.root)
            val stored = if (root === canonical.root) canonical else canonical.withRoot(root)
            trees[t.layer.ordinal] = arrayListOf(stored)
            return listOf(stored)
        }
        val staged = ArrayList(before)
        if (addInto(t, staged) == null) return emptyList()
        val after = m.canonicalFlowState(staged)
        val changes = ArrayList<FlowTree>()
        for (value in after) {
            val fresh = subtractSubsumed(value,before) ?: continue
            changes += fresh
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map { it.withRoot(interner.internIfRequired(it.root)) })
        return changes
    }

    private fun addInto(t: FlowTree, list: ArrayList<FlowTree>): FlowTree? {
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.exclusion == pending.exclusion && it.markExclusion == pending.markExclusion
            }
            if (i >= 0) {
                val rest = subtractSubsumed(pending, list) ?: return null
                val (merged, delta) = FlowAlgebra.mergeAddDelta(list[i].root, rest.root, m.cancellation)
                if (delta == null) return null
                list[i] = list[i].withRoot(interner.internIfRequired(merged))
                return m.flowTree(pending.base, pending.layer, pending.exclusion, pending.markExclusion, delta, pending.tail)
            }

            val k = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.root == pending.root &&
                    (it.markExclusion == pending.markExclusion || it.exclusion == pending.exclusion)
            }
            if (k >= 0) {
                val stored = list[k]
                val merged = m.flowTree(pending.base, pending.layer,
                    stored.exclusion.intersect(pending.exclusion),
                    stored.markExclusion.intersect(pending.markExclusion), stored.root, pending.tail)
                if (merged.exclusion == stored.exclusion && merged.markExclusion == stored.markExclusion) return null
                list.removeAt(k)
                pending = merged
                continue
            }

            val fresh = subtractSubsumed(pending, list) ?: return null
            list += fresh.withRoot(interner.internIfRequired(fresh.root))
            return fresh
        }
    }

    private fun subtractSubsumed(t: FlowTree, others: List<FlowTree>): FlowTree? {
        var root = t.root
        for (stored in others) {
            m.cancellation.checkpoint()
            val marks = stored.markExclusion.isSubsetOf(t.markExclusion)
            val atOk = marks && when (stored.tail) {
                Tail.ANY -> true
                Tail.STAR -> t.tail == Tail.STAR && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.EXACT -> t.tail == Tail.EXACT && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.ANY_TAINT -> t.tail == Tail.ANY_TAINT && stored.exclusion.isSubsetOf(t.exclusion)
            }
            val belowOk = !t.keepsDemandPositions() && marks && (stored.tail == Tail.ANY ||
                stored.tail == Tail.ANY_TAINT && t.tail == Tail.ANY_TAINT)
            root = FlowAlgebra.subtract(root, stored.root, FlowLeaf.NONE,
                at = { if (atOk) it else FlowLeaf.NONE },
                below = { if (belowOk) it else FlowLeaf.NONE },
                admits = stored.exclusion::admits,
                cancellation = m.cancellation) ?: return null
        }
        return if (root === t.root) t else t.withRoot(root)
    }
}

/** Construct a store result after its mask is proved to be included in root.
 * This is coordinate inclusion, not AP prefix coverage. General factories still trim. */
private fun admittedTree(
    m: ApManager, header: TaintTree, root: TaintNode, includedMask: TaintNode?,
    exclusion: ExclusionSet = header.exclusion,
): TaintTree = TaintTree(
    header.base, header.layer, root,
    if (!root.hasAny || header.anyTail == Tail.ANY) ExclusionSet.Empty else m.intern(exclusion),
    if (root.hasAny) header.anyTail else Tail.ANY_TAINT,
    includedMask,
)

/** TAINT values for one base. STAR and must spans keep distinct suffix semantics. */
class TaintGroup(private val m: ApManager, private val interner: TrieInterner<TaintLeaves>) {
    private val trees = arrayOf(ArrayList<TaintTree>(1), ArrayList<TaintTree>(1))

    fun all(): Sequence<TaintTree> = trees[0].asSequence() + trees[1].asSequence()

    /** Restore one complete current typed header for a temporary admission
     * adapter. Do not re-admit the snapshot: that would compact old STAR rows
     * merely because a later ANY row is already present. No history is kept. */
    internal fun restoreCurrent(t: TaintTree) {
        m.cancellation.checkpoint()
        val list = trees[t.layer.ordinal]
        check(list.none { it.anyTail == t.anyTail && it.exclusion == t.exclusion })
        list += t
    }

    fun add(t: TaintTree): TaintTree? = addAll(t).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(t: TaintTree): List<TaintTree> {
        m.cancellation.checkpoint()
        val before = trees[t.layer.ordinal]
        if (t.nonSubsumable != null || before.any { it.nonSubsumable != null })
            return addWithProtection(t, before)
        return addDataAll(t, before)
    }

    /** Preserve the existing incremental DATA order, including STAR/T4. */
    private fun addWithProtection(t: TaintTree, before: ArrayList<TaintTree>): List<TaintTree> {
        if (subtractSubsumed(t, before) == null) return emptyList()
        val temporary = TaintGroup(m, interner)
        before.forEach { temporary.restoreCurrent(it.withoutProtection()) }
        val dataChanges = temporary.addAll(t.withoutProtection())
        val after = m.embedRawProtection(temporary.all().toList(), before + t)
        val changes = LinkedHashMap<GroupKey, TaintTree>()
        fun add(value: TaintTree) {
            val old = changes[value.groupKey]
            changes[value.groupKey] = if (old == null) value else admittedTree(m, old,
                m.taintAlg.mergeAdd(old.root, value.root, m.cancellation),
                mergeProtection(old.nonSubsumable, value.nonSubsumable))
        }
        // Keep legacy whole-content T4 deltas, including their exact siblings.
        for (delta in dataChanges) for (current in retainCurrentFacts(m, delta, after))
            add(m.withCurrentProtection(current as TaintTree, after))
        for (value in after) {
            var fresh = value.nonSubsumable?.let { subtract(it, value, before, protectedOnly = true) } ?: continue
            fresh = subtract(fresh, value, changes.values.toList(), protectedOnly = true) ?: continue
            add(admittedTree(m, value, fresh, fresh))
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map {
            admittedTree(m, it, interner.internIfRequired(it.root), it.nonSubsumable)
        })
        return changes.values.toList()
    }

    private fun addDataAll(t: TaintTree, before: ArrayList<TaintTree>): List<TaintTree> {
        if (!t.root.hasAny || t.anyTail != Tail.ANY && t.anyTail != Tail.ANY_TAINT)
            return addInto(t,before)?.let(::listOf) ?: emptyList()
        if (before.isEmpty()) {
            val canonical = m.canonicalTaintPacket(t)
            val root = interner.internIfRequired(canonical.root)
            val stored = if (root === canonical.root) canonical
                else admittedTree(m,canonical,root,canonical.nonSubsumable)
            trees[t.layer.ordinal] = arrayListOf(stored)
            return listOf(stored)
        }
        // Ordinary and protected E provenance must remain separate until the
        // two streams are normalized. The old equal-root admission intersects
        // E before unioning masks and would broaden one-sided protection.
        if (subtractSubsumed(t,before) == null) return emptyList()
        val after = m.canonicalTaintState(before + t)
        val changes = ArrayList<TaintTree>()
        for (value in after) {
            val fresh = subtractSubsumed(value,before) ?: continue
            // Preserve T4's whole mixed-content delta only for an actual
            // equal-content E weakening; unrelated old exact siblings are not fresh.
            val wholeEJoin = before.any { old -> old.root.hasAny && old.root == t.root &&
                old.anyTail == t.anyTail && old.exclusion != t.exclusion &&
                value.anyTail == t.anyTail && value.root == t.root &&
                value.exclusion == old.exclusion.intersect(t.exclusion) && value.exclusion != old.exclusion }
            changes += if (wholeEJoin) value else fresh
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map {
            admittedTree(m,it,interner.internIfRequired(it.root),it.nonSubsumable)
        })
        return changes
    }

    private fun addInto(t: TaintTree, list: ArrayList<TaintTree>): TaintTree? {
        val alg = m.taintAlg
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val sameKey = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == pending.anyTail && it.exclusion == pending.exclusion
            }
            if (sameKey < 0) {
                val k = list.indexOfFirst {
                    m.cancellation.checkpoint()
                    it.anyTail == pending.anyTail && it.root == pending.root
                }
                if (k >= 0) {
                    val stored = list[k]
                    val exclusion = stored.exclusion.intersect(pending.exclusion)
                    // Equal ordinary content can still carry a new protected membership.
                    if (exclusion == stored.exclusion) {
                        val rest = subtractSubsumed(pending, list) ?: return null
                        val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
                        val root = alg.mergeAdd(stored.root, rest.root, m.cancellation)
                        list[k] = admittedTree(m, stored, interner.internIfRequired(root), protection)
                        return rest
                    }
                    list.removeAt(k)
                    pending = admittedTree(m, pending, stored.root,
                        mergeProtection(stored.nonSubsumable, pending.nonSubsumable), exclusion)
                    continue
                }
            }

            val rest = subtractSubsumed(pending, list) ?: return null
            // Subtraction can remove the last must leaf. Its canonical key is then Empty E.
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == rest.anyTail && it.exclusion == rest.exclusion
            }
            if (i < 0) {
                list += admittedTree(m, rest, interner.internIfRequired(rest.root), rest.nonSubsumable)
                return rest
            }
            val stored = list[i]
            val (merged, delta) = alg.mergeAddDelta(stored.root, rest.root, m.cancellation)
            val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
            val deltaRoot = mergeProtection(delta, rest.nonSubsumable) ?: return null
            list[i] = admittedTree(m, stored, interner.internIfRequired(merged), protection)
            return admittedTree(m, rest, deltaRoot, rest.nonSubsumable)
        }
    }

    private fun subtractSubsumed(t: TaintTree, others: List<TaintTree>): TaintTree? {
        val ordinary = subtract(t.root, t, others, protectedOnly = false)
        // Ordinary ANY coverage cannot consume a fresh protected EXACT dependency.
        val protection = t.nonSubsumable?.let { subtract(it, t, others, protectedOnly = true) }
        val root = mergeProtection(ordinary, protection) ?: return null
        if (root === t.root && protection === t.nonSubsumable) return t
        return admittedTree(m, t, root, protection)
    }

    private fun mergeProtection(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> m.taintAlg.mergeAdd(a, b, m.cancellation)
    }

    private fun subtract(root: TaintNode, t: TaintTree, others: List<TaintTree>,
                         protectedOnly: Boolean): TaintNode? {
        val alg = m.taintAlg
        var remaining = root
        for (stored in others) {
            m.cancellation.checkpoint()
            val storedRoot = if (protectedOnly) stored.nonSubsumable ?: continue else stored.root
            if (protectedOnly) {
                val sameHeader = stored.anyTail == t.anyTail && stored.exclusion == t.exclusion
                remaining = alg.subtract(remaining, storedRoot, TaintLeaves.EMPTY,
                    at = { alg.leaves(it.exact, if (sameHeader) it.any else MarkSet.EMPTY) },
                    below = { TaintLeaves.EMPTY }, cancellation = m.cancellation) ?: return null
                continue
            }
            val storedMay = stored.anyTail == Tail.ANY
            val storedStar = stored.anyTail == Tail.STAR
            val coversAny = storedMay || stored.anyTail == t.anyTail
            val anyAt = coversAny && (storedMay || stored.exclusion.isSubsetOf(t.exclusion))
            remaining = alg.subtract(remaining, storedRoot, TaintLeaves.EMPTY,
                at = { alg.leaves(if (storedMay) it.exact + it.any else it.exact,
                    if (anyAt) it.any else MarkSet.EMPTY) },
                below = { alg.leaves(if (storedMay) it.any else MarkSet.EMPTY,
                    if (coversAny && !storedStar && !t.keepsDemandPositions()) it.any else MarkSet.EMPTY) },
                admits = stored.exclusion::admits,
                cancellation = m.cancellation) ?: return null
        }
        return remaining
    }
}

/** All conclusion bases and kinds for one premise key. REACH has one bit per layer. */
class ConclusionGroup(private val m: ApManager, private val interners: StoreInterners) {
    private val reach = BooleanArray(2)
    private val flow = HashMap<AccessPathBase, FlowGroup>(2)
    private val taint = HashMap<AccessPathBase, TaintGroup>(2)

    fun add(f: Facts): Facts? = addAll(f).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(f: Facts): List<Facts> {
        m.cancellation.checkpoint()
        return when (f) {
            is Reach -> if (reach[f.layer.ordinal]) emptyList() else listOf(f.also { reach[f.layer.ordinal] = true })
            is FlowTree -> flow.getOrPut(f.base) { FlowGroup(m, interners.flow) }.addAll(f)
            is TaintTree -> taint.getOrPut(f.base) { TaintGroup(m, interners.taint) }.addAll(f)
        }
    }

    fun retainCurrent(offered: Facts): List<Facts> = retainCurrentFacts(m,offered,all().asIterable())

    fun all(): Sequence<Facts> = Layer.entries.asSequence().filter { reach[it.ordinal] }.map(Reach::of) +
        flow.values.asSequence().flatMap { it.all() } + taint.values.asSequence().flatMap { it.all() }
}

/** Soft trie caches for one store, with a separate table for each leaf kind. */
class StoreInterners(refs: SoftReferenceManager, private val cancellation: Cancellation) {
    val flow = TrieInterner<FlowLeaf>(refs, cancellation)
    val taint = TrieInterner<TaintLeaves>(refs, cancellation)

    fun internIfRequired(f: Facts): Facts {
        cancellation.checkpoint()
        return when (f) {
            is Reach -> f
            is FlowTree -> flow.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
            is TaintTree -> taint.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
        }
    }
}

package org.opentaint.dataflow.bidi.ap

import java.util.ArrayDeque

/** One immutable DAG node can occur below different admitted ancestors. */
private class SpatialKey<P : TrieLeaf>(val node: TrieNode<P>, val above: P) {
    private val hash = System.identityHashCode(node) * 31 + above.hashCode()
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is SpatialKey<*> && node === other.node && above == other.above
}
private class SpatialFrame<P : TrieLeaf>(val key: SpatialKey<P>, var expanded: Boolean = false)

/** Same-tail prefix normalization. E is read only on the first step below a
 * newly encountered span; prior inherited coverage persists across later E. */
private fun <P : TrieLeaf> LeafAlgebra<P>.canonicalSpans(
    root: TrieNode<P>, exclusion: ExclusionSet, m: ApManager,
    belowSpan: (P) -> P, samePoint: (P) -> P = { it },
): TrieNode<P> {
    val results = HashMap<SpatialKey<P>, TrieNode<P>?>()
    val start = SpatialKey(root, empty)
    val stack = ArrayDeque<SpatialFrame<P>>()
    stack.addLast(SpatialFrame(start))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (results.containsKey(key)) { stack.removeLast(); continue }
        val next = union(key.above, belowSpan(key.node.leaf))
        if (!frame.expanded) {
            frame.expanded = true
            key.node.accessorData?.forEachIndexed { i, accessor ->
                val child = SpatialKey(key.node.childData!![i], if (exclusion.admits(accessor)) next else key.above)
                if (!results.containsKey(child)) stack.addLast(SpatialFrame(child))
            }
        } else {
            val leaf = samePoint(minus(key.node.leaf, key.above))
            results[key] = mapChildren(key.node, leaf, m.cancellation) { accessor, child ->
                results.getValue(SpatialKey(child, if (exclusion.admits(accessor)) next else key.above))
            }
            stack.removeLast()
        }
    }
    return checkNotNull(results.getValue(start)) { "A nonempty packet has a minimal retained position" }
}

/** Explicit MAY positions guide later refinement even when an ancestor covers
 * their denotation. This applies to real FLOW packets, not TAINT geometry. */
internal fun FlowTree.keepsDemandPositions(): Boolean = layer == Layer.DEMAND && tail == Tail.ANY
internal fun TaintTree.keepsDemandPositions(): Boolean = layer == Layer.DEMAND && anyTail == Tail.ANY

internal fun ApManager.canonicalFlowPacket(value: FlowTree): FlowTree =
    if (value.keepsDemandPositions()) value else canonicalFlowDataPacket(value)

/** DATA normalization is also used by packed TAINT's temporary FLOW geometry. */
internal fun ApManager.canonicalFlowDataPacket(value: FlowTree): FlowTree {
    if (value.tail != Tail.ANY && value.tail != Tail.ANY_TAINT) return value
    if (value.root.childData == null) return value
    val root = FlowAlgebra.canonicalSpans(value.root, value.exclusion, this, { it })
    return if (root === value.root) value else value.withRoot(root)
}

internal fun ApManager.canonicalTaintPacket(value: TaintTree): TaintTree {
    if (value.anyTail != Tail.ANY && value.anyTail != Tail.ANY_TAINT || !value.root.hasAny) return value
    if (value.root.childData == null && (value.anyTail != Tail.ANY || value.root.leaf.exact.isEmpty)) return value
    val may = value.anyTail == Tail.ANY
    fun below(leaf: TaintLeaves) = taintLeaves(if (may) leaf.any else MarkSet.EMPTY,
        if (value.keepsDemandPositions()) MarkSet.EMPTY else leaf.any)
    fun at(leaf: TaintLeaves) = if (may) taintLeaves(leaf.exact - leaf.any, leaf.any) else leaf
    val ordinary = taintAlg.canonicalSpans(value.root, value.exclusion, this, ::below, ::at)
    val protection = value.nonSubsumable
    // Native masks require coordinate inclusion even when plain ancestor
    // support is spatially broader than the protected dependency.
    val root = if (protection == null) ordinary else taintAlg.mergeAdd(ordinary, protection, cancellation)
    return if (root === value.root && protection === value.nonSubsumable) value
        else taintTree(value.base, value.layer, root, value.exclusion, value.anyTail, protection)
}

/** Packet-local canonical C2 input. The list contract also supports callers
 * consuming the multi-header deltas returned by canonical group admission. */
fun ApManager.canonicalPackets(value: Facts): List<Facts> = listOf(when (value) {
    is Reach -> value
    is FlowTree -> canonicalFlowPacket(value)
    is TaintTree -> canonicalTaintPacket(value)
})

/** A cohort changes no semantic key: channel is mx for FLOW and Unit for a
 * concrete mark-mask stream. E remains a separate rooted-region payload. */
internal data class SpatialRegion<P : TrieLeaf, K>(
    val tail: Tail, val exclusion: ExclusionSet, val channel: K, val root: TrieNode<P>,
)
private data class SpatialHeader<K>(val tail: Tail, val exclusion: ExclusionSet, val channel: K)

private fun <P : TrieLeaf> LeafAlgebra<P>.intersectionAt(
    a: TrieNode<P>, b: TrieNode<P>, m: ApManager,
): TrieNode<P>? {
    if (a === b) return a
    val outside = minusNode(a, b, m.cancellation) ?: return a
    return minusNode(a, outside, m.cancellation)
}

private class FillKey<P : TrieLeaf>(val parent: TrieNode<P>, val child: TrieNode<P>?) {
    private val hash = System.identityHashCode(parent) * 31 + System.identityHashCode(child)
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is FillKey<*> && parent === other.parent && child === other.child
}
private class FillFrame<P : TrieLeaf>(val key: FillKey<P>, var expanded: Boolean = false)

/** Partition only the leaf masks whose complete immediate child fills E.
 * The pair DAG memo avoids path enumeration, including shared subtrees. */
private fun <P : TrieLeaf> LeafAlgebra<P>.fillImmediate(
    parent: TrieNode<P>, completeChildren: TrieNode<P>, exclusion: ExclusionSet.Concrete, m: ApManager,
): Map<ExclusionSet, TrieNode<P>> {
    val results = HashMap<FillKey<P>, Map<ExclusionSet, TrieNode<P>>>()
    val start = FillKey(parent, completeChildren)
    val stack = ArrayDeque<FillFrame<P>>()
    stack.addLast(FillFrame(start))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (results.containsKey(key)) { stack.removeLast(); continue }
        if (key.child == null) {
            results[key] = mapOf(exclusion to key.parent)
            stack.removeLast()
            continue
        }
        if (!frame.expanded) {
            frame.expanded = true
            key.parent.accessorData?.forEachIndexed { i, field ->
                val childKey = FillKey(key.parent.childData!![i], key.child.child(field))
                if (!results.containsKey(childKey)) stack.addLast(FillFrame(childKey))
            }
        } else {
            var leaves = linkedMapOf<ExclusionSet, P>()
            if (!key.parent.leaf.isEmpty) leaves[exclusion] = key.parent.leaf
            for (field in exclusion.data) {
                m.cancellation.checkpoint()
                val support = key.child.child(field)?.leaf ?: continue
                if (support.isEmpty) continue
                val split = LinkedHashMap<ExclusionSet, P>()
                for ((e, leaf) in leaves) {
                    val yes = minus(leaf, minus(leaf, support))
                    val no = minus(leaf, support)
                    if (!no.isEmpty) split[e] = split[e]?.let { union(it, no) } ?: no
                    if (!yes.isEmpty) {
                        val next = m.intern(ExclusionSet.of((e as? ExclusionSet.Concrete)?.data
                            ?.filter { it != field }?.toIntArray() ?: EMPTY_PATH))
                        split[next] = split[next]?.let { union(it, yes) } ?: yes
                    }
                }
                leaves = split
            }
            val headers = LinkedHashSet<ExclusionSet>()
            headers.addAll(leaves.keys)
            key.parent.accessorData?.forEachIndexed { i, field ->
                headers.addAll(results.getValue(FillKey(key.parent.childData!![i], key.child.child(field))).keys)
            }
            val out = LinkedHashMap<ExclusionSet, TrieNode<P>>()
            for (e in headers) {
                val fields = ArrayList<Int>()
                val children = ArrayList<TrieNode<P>>()
                var unchanged = e == exclusion
                key.parent.accessorData?.forEachIndexed { i, field ->
                    val old = key.parent.childData!![i]
                    val child = results.getValue(FillKey(old, key.child.child(field)))[e]
                    unchanged = unchanged && child === old
                    if (child != null) { fields += field; children += child }
                }
                val leaf = leaves[e] ?: empty
                val result = if (unchanged && leaf == key.parent.leaf) key.parent
                    else node(leaf, fields.toIntArray(), children.toTypedArray())
                if (!result.isEmpty) out[e] = result
            }
            results[key] = out
            stack.removeLast()
        }
    }
    return results.getValue(start)
}

private fun <P : TrieLeaf, K> LeafAlgebra<P>.coalesceRegions(
    values: List<SpatialRegion<P, K>>, m: ApManager,
): List<SpatialRegion<P, K>> {
    val roots = LinkedHashMap<SpatialHeader<K>, TrieNode<P>>()
    for (v in values) {
        m.cancellation.checkpoint()
        if (v.root.isEmpty) continue
        val key = SpatialHeader(v.tail, v.exclusion, v.channel)
        roots[key] = roots[key]?.let { mergeAdd(it, v.root, m.cancellation) } ?: v.root
    }
    return roots.map { (h, root) -> SpatialRegion(h.tail, h.exclusion, h.channel, root) }
}

/** Constructive region rules from Canonical.lean, executed over packed DAGs.
 * FLOW channels never split into positive mark sets: caller-supplied full
 * channel support is required for a cover or a complete-child fill. */
internal fun <P : TrieLeaf, K> LeafAlgebra<P>.canonicalRegions(
    input: List<SpatialRegion<P, K>>, m: ApManager,
    equalEJoin: ((K,K) -> K)? = null,
    preserveAnyHeads: Boolean = false,
    channelCovers: (K, K) -> Boolean,
): List<SpatialRegion<P, K>> {
    var current = coalesceRegions(input, m)
    while (true) {
        m.cancellation.checkpoint()
        // Equal E makes the cofinite payload union exactly representable.
        // Join only shared coordinates; unrelated geometry keeps its old mx.
        var channelJoined = false
        if (equalEJoin != null) channelJoin@ for (i in current.indices) {
            val a = current[i]
            if (a.tail != Tail.ANY && a.tail != Tail.ANY_TAINT) continue
            for (j in i + 1 until current.size) {
                val b = current[j]
                if (b.tail != a.tail || b.exclusion != a.exclusion || b.channel == a.channel) continue
                val common = intersectionAt(a.root,b.root,m) ?: continue
                val next = ArrayList<SpatialRegion<P,K>>(current.size + 1)
                for (k in current.indices) if (k != i && k != j) next += current[k]
                minusNode(a.root,common,m.cancellation)?.let { next += a.copy(root = it) }
                minusNode(b.root,common,m.cancellation)?.let { next += b.copy(root = it) }
                next += a.copy(channel = equalEJoin(a.channel,b.channel),root = common)
                current = coalesceRegions(next,m)
                channelJoined = true
                break@channelJoin
            }
        }
        if (channelJoined) continue
        // Join shared coordinates of same-channel MUST cohorts by E intersection.
        var joined = false
        join@ for (i in current.indices) {
            val a = current[i]
            if (a.tail != Tail.ANY_TAINT) continue
            for (j in i + 1 until current.size) {
                val b = current[j]
                if (b.tail != a.tail || b.channel != a.channel || b.exclusion == a.exclusion) continue
                val common = intersectionAt(a.root, b.root, m) ?: continue
                val next = ArrayList<SpatialRegion<P, K>>(current.size + 1)
                for (k in current.indices) if (k != i && k != j) next += current[k]
                minusNode(a.root, common, m.cancellation)?.let { next += a.copy(root = it) }
                minusNode(b.root, common, m.cancellation)?.let { next += b.copy(root = it) }
                next += a.copy(exclusion = m.intern(a.exclusion.intersect(b.exclusion)), root = common)
                current = coalesceRegions(next, m)
                joined = true
                break@join
            }
        }
        if (joined) continue
        // A child channel must supply ALL parent marks. Narrower FLOW children
        // remain separate; concrete masks split only their already finite bits.
        var filled = false
        fill@ for (i in current.indices) {
            val parent = current[i]
            val e = parent.exclusion as? ExclusionSet.Concrete ?: continue
            if (parent.tail != Tail.ANY_TAINT) continue
            for (j in current.indices) {
                val child = current[j]
                if (child.tail != Tail.ANY_TAINT || child.exclusion != ExclusionSet.Empty ||
                    !channelCovers(child.channel, parent.channel)) continue
                val split = fillImmediate(parent.root, child.root, e, m)
                if (split.size == 1 && split[e] === parent.root) continue
                val next = ArrayList<SpatialRegion<P, K>>(current.size + split.size)
                for (k in current.indices) if (k != i) next += current[k]
                for ((nextE, root) in split) next += parent.copy(exclusion = nextE, root = root)
                current = coalesceRegions(next, m)
                filled = true
                break@fill
            }
        }
        if (filled) continue
        // New prefix coverage applies to compatible equal tail kinds. The
        // original admission path still owns its pre-existing cross-tail law.
        val next = ArrayList<SpatialRegion<P, K>>(current.size)
        var changed = false
        for (i in current.indices) {
            val value = current[i]
            val keepHeads = preserveAnyHeads && value.tail == Tail.ANY
            var root: TrieNode<P>? = if (!keepHeads && (value.tail == Tail.ANY || value.tail == Tail.ANY_TAINT))
                canonicalSpans(value.root, value.exclusion, m, { it }) else value.root
            for (j in current.indices) {
                if (i == j || root == null) continue
                val stored = current[j]
                if (stored.tail != value.tail || !channelCovers(stored.channel, value.channel)) continue
                val sameAt = stored.tail == Tail.ANY || stored.exclusion.isSubsetOf(value.exclusion)
                val equivalent = sameAt && (stored.tail == Tail.ANY || value.exclusion.isSubsetOf(stored.exclusion)) &&
                    channelCovers(value.channel, stored.channel)
                // Equivalent cohort headers can overlap at coordinates. Keep
                // their first witness, never subtract the same point twice.
                val atAllowed = sameAt && (!equivalent || j < i)
                val belowAllowed = !keepHeads && (stored.tail == Tail.ANY || stored.tail == Tail.ANY_TAINT)
                root = subtract(root, stored.root, empty,
                    at = { if (atAllowed) it else empty },
                    below = { if (belowAllowed) it else empty },
                    admits = stored.exclusion::admits, cancellation = m.cancellation)
            }
            changed = changed || root !== value.root
            if (root != null) next += value.copy(root = root)
        }
        if (!changed) return current
        current = coalesceRegions(next, m)
    }
}

internal fun ApManager.canonicalFlowState(values: List<FlowTree>): List<FlowTree> {
    if (values.isEmpty()) return values
    val first = values[0]
    return FlowAlgebra.canonicalRegions(values.map {
        check(it.base == first.base && it.layer == first.layer)
        SpatialRegion(it.tail,it.exclusion,it.markExclusion,it.root)
    },this,equalEJoin = { a,b -> intern(a.intersect(b)) },preserveAnyHeads = first.layer == Layer.DEMAND,
        channelCovers = MarkExclusions::isSubsetOf).map { flowTree(first.base, first.layer, it.exclusion, it.channel, it.root, it.tail) }
}

private data class TaintSpatialHeader(val tail: Tail, val exclusion: ExclusionSet)
private class TaintSpatialRoots(var ordinary: TaintNode? = null, var protected: TaintNode? = null)

internal fun ApManager.canonicalTaintState(values: List<TaintTree>): List<TaintTree> {
    if (values.none { it.nonSubsumable != null }) return canonicalTaintDataState(values)
    return embedRawProtection(canonicalTaintDataState(values.map { it.withoutProtection() }), values)
}

/** The existing regional DATA step. STAR/T4 admission remains in TaintGroup. */
private fun ApManager.canonicalTaintDataState(values: List<TaintTree>): List<TaintTree> {
    if (values.isEmpty()) return values
    val first = values[0]
    fun union(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> taintAlg.mergeAdd(a,b,cancellation)
    }
    fun extract(root: TaintNode, any: Boolean): TaintNode? = taintAlg.mapCanonicalLeaves(root,cancellation) {
        if (any) taintLeaves(MarkSet.EMPTY,it.any) else taintLeaves(it.exact,MarkSet.EMPTY)
    }
    val ordinary = ArrayList<SpatialRegion<TaintLeaves,Unit>>()
    val protected = ArrayList<SpatialRegion<TaintLeaves,Unit>>()
    val exactHeaders = LinkedHashMap<TaintSpatialHeader,TaintSpatialRoots>()
    // Only byte-equal whole ordinary content has the old T4 mixed-header join.
    val contentE = HashMap<Pair<Tail,TaintNode>,ExclusionSet>()
    for (value in values) {
        cancellation.checkpoint()
        check(value.base == first.base && value.layer == first.layer)
        val header = TaintSpatialHeader(value.anyTail,value.exclusion)
        val exact = exactHeaders.getOrPut(header,::TaintSpatialRoots)
        exact.ordinary = union(exact.ordinary,extract(value.root,false))
        extract(value.root,true)?.let { ordinary += SpatialRegion(value.anyTail,value.exclusion,Unit,it) }
        if (value.root.hasAny) {
            val key = value.anyTail to value.root
            contentE[key] = contentE[key]?.intersect(value.exclusion) ?: value.exclusion
        }
        value.nonSubsumable?.let { flags ->
            exact.protected = union(exact.protected,extract(flags,false))
            extract(flags,true)?.let { protected += SpatialRegion(value.anyTail,value.exclusion,Unit,it) }
        }
    }
    val ordinarySpans = taintAlg.canonicalRegions(ordinary,this,
        preserveAnyHeads = first.layer == Layer.DEMAND) { _,_ -> true }
    val protectedSpans = taintAlg.canonicalRegions(protected,this) { _,_ -> true }
    fun pruneExact(root: TaintNode?, spans: List<SpatialRegion<TaintLeaves,Unit>>): TaintNode? {
        var current = root
        for (span in spans) if (span.tail == Tail.ANY && current != null) {
            current = taintAlg.subtract(current,span.root,TaintLeaves.EMPTY,
                at = { taintLeaves(it.any,MarkSet.EMPTY) }, below = { taintLeaves(it.any,MarkSet.EMPTY) },
                cancellation = cancellation)
        }
        return current
    }
    val grouped = LinkedHashMap<TaintSpatialHeader,TaintSpatialRoots>()
    for (span in ordinarySpans) {
        val roots = grouped.getOrPut(TaintSpatialHeader(span.tail,span.exclusion),::TaintSpatialRoots)
        roots.ordinary = union(roots.ordinary,span.root)
    }
    for (span in protectedSpans) {
        val roots = grouped.getOrPut(TaintSpatialHeader(span.tail,span.exclusion),::TaintSpatialRoots)
        roots.protected = union(roots.protected,span.root)
    }
    var seenExact: TaintNode? = null
    var seenProtectedExact: TaintNode? = null
    for ((oldHeader,exact) in exactHeaders) {
        var destination = oldHeader.takeIf { it in grouped }
        if (destination == null) {
            // Keep unchanged exact coordinates in their old mixed cohort where
            // possible. A real equal-content T4 join may move that cohort.
            for (value in values) if (value.anyTail == oldHeader.tail && value.exclusion == oldHeader.exclusion && value.root.hasAny) {
                val joined = TaintSpatialHeader(value.anyTail,contentE.getValue(value.anyTail to value.root))
                if (joined in grouped) { destination = joined; break }
            }
        }
        val header = destination ?: TaintSpatialHeader(Tail.ANY_TAINT,ExclusionSet.Empty)
        val ordinaryExact = pruneExact(exact.ordinary,ordinarySpans)?.let { root ->
            if (seenExact == null) root else taintAlg.minusNode(root,checkNotNull(seenExact),cancellation)
        }
        val protectedExact = pruneExact(exact.protected,protectedSpans)?.let { root ->
            if (seenProtectedExact == null) root else taintAlg.minusNode(root,checkNotNull(seenProtectedExact),cancellation)
        }
        if (ordinaryExact == null && protectedExact == null) continue
        val roots = grouped.getOrPut(header,::TaintSpatialRoots)
        roots.ordinary = union(roots.ordinary,ordinaryExact)
        roots.protected = union(roots.protected,protectedExact)
        seenExact = union(seenExact,ordinaryExact)
        seenProtectedExact = union(seenProtectedExact,protectedExact)
    }
    return grouped.mapNotNull { (header,roots) ->
        val root = union(roots.ordinary,roots.protected) ?: return@mapNotNull null
        taintTree(first.base,first.layer,root,header.exclusion,header.tail,roots.protected)
    }
}

/** Retain supplied protection by effective scalar coordinates. DATA-derived
 * E joins stay plain. EXACT ignores its wrapper; span masks retain tail/E. */
internal fun ApManager.embedRawProtection(data: List<TaintTree>, sources: List<TaintTree>): List<TaintTree> {
    if (sources.none { it.nonSubsumable != null }) return data
    val first = sources.first()
    fun union(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> taintAlg.mergeAdd(a, b, cancellation)
    }
    fun exact(root: TaintNode): TaintNode? = taintAlg.mapCanonicalLeaves(root, cancellation) {
        taintLeaves(it.exact, MarkSet.EMPTY)
    }
    fun minus(a: TaintNode?, b: TaintNode?): TaintNode? =
        if (a == null || b == null) a else taintAlg.minusNode(a, b, cancellation)

    var exactFlags: TaintNode? = null
    for (source in sources) {
        cancellation.checkpoint()
        check(source.base == first.base && source.layer == first.layer)
        source.nonSubsumable?.let { exactFlags = union(exactFlags, exact(it)) }
    }
    val grouped = LinkedHashMap<TaintSpatialHeader, TaintSpatialRoots>()
    fun add(header: TaintSpatialHeader, root: TaintNode, flags: TaintNode?) {
        val key = if (root.hasAny || grouped[header]?.ordinary?.hasAny == true) header
            else TaintSpatialHeader(Tail.ANY_TAINT, ExclusionSet.Empty)
        val target = grouped.getOrPut(key, ::TaintSpatialRoots)
        target.ordinary = union(target.ordinary, root)
        target.protected = union(target.protected, flags)
    }
    var placedExact: TaintNode? = null
    for (value in data) {
        cancellation.checkpoint()
        check(value.nonSubsumable == null && value.base == first.base && value.layer == first.layer)
        val matching = exactFlags?.let { intersectTaintMask(it, value.root, cancellation) }
        val repeated = if (matching == null || placedExact == null) null
            else intersectTaintMask(matching, checkNotNull(placedExact), cancellation)
        val root = minus(value.root, repeated) ?: continue
        val flags = minus(matching, placedExact)
        add(TaintSpatialHeader(value.anyTail, value.exclusion), root, flags)
        placedExact = union(placedExact, flags)
    }
    for (source in sources) {
        cancellation.checkpoint()
        val flags = source.nonSubsumable ?: continue
        val spans = taintAlg.mapCanonicalLeaves(flags, cancellation) { taintLeaves(MarkSet.EMPTY, it.any) }
        if (spans != null) add(TaintSpatialHeader(source.anyTail, source.exclusion), spans, spans)
    }
    // Restore pruned exact flags in an existing original cohort where possible.
    // This keeps whole-content T4 geometry without duplicating effective EXACT.
    for (source in sources) {
        cancellation.checkpoint()
        val header = TaintSpatialHeader(source.anyTail, source.exclusion)
        if (header !in grouped) continue
        val flags = minus(source.nonSubsumable?.let(::exact), placedExact) ?: continue
        add(header, flags, flags)
        placedExact = union(placedExact, flags)
    }
    minus(exactFlags, placedExact)?.let {
        add(TaintSpatialHeader(Tail.ANY_TAINT, ExclusionSet.Empty), it, it)
    }
    return grouped.mapNotNull { (header, roots) ->
        roots.ordinary?.let { taintTree(first.base, first.layer, it, header.exclusion, header.tail, roots.protected) }
    }
}

/** Copy only already-current flags onto a legacy DATA delta. No prefix overlap. */
internal fun ApManager.withCurrentProtection(value: TaintTree, current: List<TaintTree>): TaintTree {
    var mask: TaintNode? = null
    for (stored in current) {
        cancellation.checkpoint()
        if (stored.base != value.base || stored.layer != value.layer) continue
        val flags = stored.nonSubsumable ?: continue
        val typed = if (stored.anyTail == value.anyTail && stored.exclusion == value.exclusion) flags
            else taintAlg.mapCanonicalLeaves(flags, cancellation) { taintLeaves(it.exact, MarkSet.EMPTY) } ?: continue
        val common = intersectTaintMask(typed, value.root, cancellation) ?: continue
        mask = mask?.let { taintAlg.mergeAdd(it, common, cancellation) } ?: common
    }
    return value.withProtection(mask, cancellation)
}

/** Read current exact coordinates, not semantic ancestor coverage. A final
 * detached batch cannot retain a removed descendant through its old snapshot.
 * Exact TAINT slots ignore a wrapper's any-tail/E, as native scalar leaves do. */
fun retainCurrentFacts(m: ApManager, offered: Facts, current: Iterable<Facts>): List<Facts> {
    m.cancellation.checkpoint()
    return when (offered) {
        is Reach -> if (current.any { it is Reach && it.layer == offered.layer }) listOf(offered) else emptyList()
        is FlowTree -> {
            var root: FlowNode? = null
            for (value in current) {
                m.cancellation.checkpoint()
                if (value !is FlowTree || value.groupKey != offered.groupKey) continue
                val common = FlowAlgebra.intersectionAt(offered.root,value.root,m) ?: continue
                root = root?.let { FlowAlgebra.mergeAdd(it,common,m.cancellation) } ?: common
            }
            root?.let { listOf(offered.withRoot(it)) } ?: emptyList()
        }
        is TaintTree -> {
            var ordinary: TaintNode? = null
            var protected: TaintNode? = null
            fun selected(value: TaintTree, root: TaintNode): TaintNode? {
                val matching = value.anyTail == offered.anyTail && value.exclusion == offered.exclusion
                return if (matching) root else m.taintAlg.mapCanonicalLeaves(root,m.cancellation) {
                    m.taintLeaves(it.exact,MarkSet.EMPTY)
                }
            }
            for (value in current) {
                m.cancellation.checkpoint()
                if (value !is TaintTree || value.base != offered.base || value.layer != offered.layer) continue
                selected(value,value.root)?.let { mask ->
                    intersectTaintMask(offered.root,mask,m.cancellation)?.let { common ->
                        ordinary = ordinary?.let { m.taintAlg.mergeAdd(it,common,m.cancellation) } ?: common
                    }
                }
                if (offered.nonSubsumable != null && value.nonSubsumable != null) {
                    selected(value,value.nonSubsumable)?.let { mask ->
                        intersectTaintMask(offered.nonSubsumable,mask,m.cancellation)?.let { common ->
                            protected = protected?.let { m.taintAlg.mergeAdd(it,common,m.cancellation) } ?: common
                        }
                    }
                }
            }
            ordinary?.let { listOf(m.taintTree(offered.base,offered.layer,it,offered.exclusion,offered.anyTail,protected)) }
                ?: emptyList()
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Exact diagonal relations for the current runtime atoms.
 * A row has one immutable typed output geometry and two exact mark masks.
 * No original scalar tree or historical row is retained behind the masks. */
class DiagonalRelations(private val m: ApManager, private val interners: StoreInterners = m.newInterners()) {
    private data class Scope(val initial: InitialAp, val base: AccessPathBase, val layer: Layer)
    private data class Header(val scope: Scope, val tail: Tail, val exclusion: ExclusionSet) {
        constructor(initial: InitialAp, base: AccessPathBase, layer: Layer, tail: Tail, exclusion: ExclusionSet) :
            this(Scope(initial, base, layer), tail, exclusion)
        val initial get() = scope.initial
        val base get() = scope.base
        val layer get() = scope.layer
    }
    private class Masks(var marks: MarkSet, var protected: MarkSet)
    /** The common case reuses the geometry map object. Siblings allocate no
     * second index, per-scope map or per-header entry; they stay in this scope. */
    private class Rows(val tail: Tail, val exclusion: ExclusionSet) : LinkedHashMap<FlowNode, Masks>() {
        var next: Rows? = null
    }
    private val headers = LinkedHashMap<Scope, Rows>()

    private fun findRows(header: Header): Rows? {
        var current = headers[header.scope]
        while (current != null) {
            m.cancellation.checkpoint()
            if (current.tail == header.tail && current.exclusion == header.exclusion) return current
            current = current.next
        }
        return null
    }

    private fun rowsFor(header: Header): Rows {
        var current = headers[header.scope]
            ?: return Rows(header.tail, header.exclusion).also { headers[header.scope] = it }
        while (true) {
            m.cancellation.checkpoint()
            val rows = current
            if (rows.tail == header.tail && rows.exclusion == header.exclusion) return rows
            val next = rows.next
            if (next == null) return Rows(header.tail, header.exclusion).also { rows.next = it }
            current = next
        }
    }

    private fun removeHeader(header: Header) {
        var previous: Rows? = null
        var current = headers[header.scope]
        while (current != null) {
            if (current.tail == header.tail && current.exclusion == header.exclusion) {
                if (previous == null) {
                    val next = current.next
                    if (next == null) headers.remove(header.scope) else headers[header.scope] = next
                } else previous.next = current.next
                current.next = null
                return
            }
            previous = current
            current = current.next
        }
    }

    private fun scopedRows(scope: Scope): Sequence<Pair<Header, Rows>> = sequence {
        var current = headers[scope]
        while (current != null) {
            m.cancellation.checkpoint()
            val rows = current
            yield(Header(scope, rows.tail, rows.exclusion) to rows)
            current = rows.next
        }
    }

    private fun allRows(): Sequence<Pair<Header, Rows>> = sequence {
        for (scope in headers.keys) yieldAll(scopedRows(scope))
    }

    val isEmpty: Boolean get() = headers.isEmpty()
    val rowCount: Int get() = allRows().sumOf { it.second.size }
    val markMembershipCount: Int get() = allRows().sumOf { (_, rows) -> rows.values.sumOf { it.marks.size } }

    /** Scan exact masks without constructing their scalar decoded trees. */
    fun census(): RelationCensus = census(RelationCensusCounter(m.cancellation))

    internal fun census(counter: RelationCensusCounter,
                        include: (PremiseKey, Layer) -> Boolean = { _, _ -> true }): RelationCensus {
        m.cancellation.checkpoint()
        var result = RelationCensus.ZERO
        for ((header, rows) in allRows()) {
            // Diagonal scopes are nonzero singleton premises. Selection does not decode a mark.
            if (!include(header.initial, header.layer)) continue
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                val outputs = counter.flowAnnotations(shape)
                result += RelationCensus(
                    concreteOutputMemberships = Math.multiplyExact(outputs, masks.marks.size.toLong()),
                    protectedOutputMemberships = Math.multiplyExact(outputs, masks.protected.size.toLong()),
                    diagonalGeometryRows = 1,
                    diagonalMarkRows = masks.marks.size.toLong(),
                )
            }
        }
        return result
    }

    /** Same-geometry mask admission. Null selects the scalar fallback before
     * mutation; an empty list means the whole offered mask was already stored.
     * Different geometry for an overlapping mark needs the existing spatial
     * subtraction/protection adapter and is deliberately not guessed here. */
    fun addDiagonal(offered: DiagonalDelta): List<DiagonalDelta>? {
        m.cancellation.checkpoint()
        // Every legal ANY packet is DEMAND and each supplied head is a guide.
        // Uniformly protected packets also retain their literal coordinates.
        if (offered.tail == Tail.ANY && offered.layer != Layer.DEMAND) return null
        val delta = offered
        if (!RuntimeDataDomain.initial(delta.initialShape) || !RuntimeDataDomain.base(delta.base)) return emptyList()
        require(delta.initialShape.manager === m) { "A diagonal packet must use this AP manager" }
        val header = Header(delta.initialShape, delta.base, delta.layer, delta.tail, delta.exclusion)
        // A different tail/E header can already cover some offered atoms.
        // Keep packet admission atomic and use the exact scalar adapter below.
        if (hasOtherHeader(header, delta.marks)) return null
        val previous = findRows(header)
        if (previous != null) for ((shape, masks) in previous) {
            m.cancellation.checkpoint()
            if (!(masks.marks intersect delta.marks).isEmpty && shape != delta.geometry) return null
        }
        val old = previous?.get(delta.geometry)
        val fresh = m.intern(delta.marks - (old?.marks ?: MarkSet.EMPTY))
        val flagged = if (delta.protected)
            m.intern(delta.marks - (old?.protected ?: MarkSet.EMPTY)) else MarkSet.EMPTY
        if (fresh.isEmpty && flagged.isEmpty) return emptyList()
        val rows = previous ?: rowsFor(header)
        admit(rows, delta.geometry, delta.marks, if (delta.protected) delta.marks else MarkSet.EMPTY)
        val output = ArrayList<DiagonalDelta>(2)
        if (!delta.protected && !fresh.isEmpty) output += delta.copy(marks = fresh, protected = false)
        if (!flagged.isEmpty) output += delta.copy(marks = flagged, protected = true)
        return output
    }

    fun supports(premise: PremiseKey, facts: Facts): Boolean {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, facts)) return false
        val f = facts as? TaintTree ?: return false
        if ((f.anyTail != Tail.STAR && f.anyTail != Tail.ANY) ||
            flowInitialForCoverage(m, premise) == null) return false
        val mark = ((premise as InitialAp).mark as MarkSlot.Concrete).mark
        val all = m.taintAlg.foldAll(f.root, m.cancellation)
        if (!all.exact.isEmpty || all.any != m.markSetOf(mark)) return false
        val flags = f.nonSubsumable?.let { m.taintAlg.foldAll(it, m.cancellation) }
        return flags == null || (flags.exact.isEmpty && flags.any.isSubsetOf(all.any))
    }

    /** Admit geometry/mask memberships before constructing the one scalar
     * delta needed by the current interpreter interface. */
    fun add(premise: PremiseKey, facts: Facts): Facts? = addAll(premise,facts).also {
        check(it.size <= 1) { "Canonical diagonal admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(premise: PremiseKey, facts: Facts): List<Facts> {
        if (!RuntimeDataDomain.packet(premise,facts)) return emptyList()
        require(supports(premise,facts)) { "Only admitted diagonal STAR or ANY relations use this store" }
        val f = facts as TaintTree
        val initial = premise as InitialAp
        val mark = (initial.mark as MarkSlot.Concrete).mark
        val scope = Scope(checkNotNull(flowInitialForCoverage(m,premise)), f.base, f.layer)
        val header = Header(scope, f.anyTail, f.exclusion)
        val scalar = f.anyTail == Tail.ANY || f.nonSubsumable != null ||
            hasOtherHeader(header, m.markSetOf(mark)) || scopedRows(scope).any { (_, rows) ->
                rows.values.any { mark in it.protected }
            }
        if (!scalar) return addOne(premise, f)?.let(::listOf) ?: emptyList()
        val before = currentAtom(scope,mark)
        val temporary = TaintGroup(m,interners.taint)
        before.values.forEach(temporary::restoreCurrent)
        val changes = temporary.addAll(m.canonicalTaintPacket(f))
        val after = LinkedHashMap<Header,TaintTree>()
        for (value in temporary.all()) after[Header(scope.initial,value.base,value.layer,value.anyTail,value.exclusion)] = value
        replaceAtom(scope,mark,after)
        return changes
    }

    private fun addOne(premise: PremiseKey, facts: Facts): Facts? {
        if (!RuntimeDataDomain.packet(premise, facts)) return null
        require(supports(premise, facts)) { "Only admitted diagonal STAR or ANY relations use this store" }
        val f = facts as TaintTree
        val initial = premise as InitialAp
        val mark = (initial.mark as MarkSlot.Concrete).mark
        val one = m.markSetOf(mark)
        val header = Header(checkNotNull(flowInitialForCoverage(m, premise)), f.base, f.layer, f.anyTail, f.exclusion)
        val rows = rowsFor(header)
        val offered = geometry(f.root)
        var fresh: FlowNode? = offered

        // Capture only current rows for this operation. Mutations below replace
        // their mask membership; this list is not retained by the owner.
        for ((shape, masks) in rows.entries.toList()) {
            m.cancellation.checkpoint()
            if (mark !in masks.marks) continue
            fresh = fresh?.let { subtract(it, shape, header.tail) }
        }
        val delta = fresh ?: return null
        admit(rows, delta, one, MarkSet.EMPTY)
        return decode(header, delta, mark, null)
    }

    private fun hasOtherHeader(offered: Header, marks: MarkSet): Boolean {
        var current = headers[offered.scope]
        while (current != null) {
            m.cancellation.checkpoint()
            if (current.tail != offered.tail || current.exclusion != offered.exclusion) {
                for (masks in current.values) {
                    m.cancellation.checkpoint()
                    if (!(masks.marks intersect marks).isEmpty) return true
                }
            }
            current = current.next
        }
        return false
    }

    private fun currentAtom(scope: Scope, mark: TaintMark): LinkedHashMap<Header,TaintTree> {
        val before = LinkedHashMap<Header, TaintTree>()
        for ((header, rows) in scopedRows(scope)) {
            m.cancellation.checkpoint()
            var root: FlowNode? = null
            var flags: FlowNode? = null
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                if (mark !in masks.marks) continue
                root = union(root, shape)
                if (mark in masks.protected) flags = union(flags, shape)
            }
            if (root != null) before[header] = decode(header, root, mark, flags)
        }
        return before
    }

    private fun replaceAtom(scope: Scope, mark: TaintMark, after: Map<Header,TaintTree>) {
        // Prepare the replacement off-store. Cancellation must not leave an
        // empty header, a stale sibling, or a half-rewritten shared T/U mask.
        val one = m.markSetOf(mark)
        val replacement = LinkedHashMap<Header, Rows>()
        for ((header, rows) in scopedRows(scope)) {
            m.cancellation.checkpoint()
            val kept = Rows(header.tail, header.exclusion)
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                // Masks are mutable. Keep immutable sets, but do not let
                // local re-encoding change a still-published shared mask.
                if (mark !in masks.marks) kept[shape] = Masks(masks.marks, masks.protected) else {
                    val rest = m.intern(masks.marks - one)
                    if (!rest.isEmpty) kept[shape] = Masks(rest, m.intern(masks.protected - one))
                }
            }
            if (kept.isNotEmpty()) replacement[header] = kept
        }
        for ((header, value) in after) {
            m.cancellation.checkpoint()
            val root = geometry(value.root)
            val flags = value.nonSubsumable?.let(::geometry)
            val plain = if (flags == null) root else subtractExact(root, flags)
            val rows = replacement.getOrPut(header) { Rows(header.tail, header.exclusion) }
            if (plain != null) admit(rows, plain, one, MarkSet.EMPTY)
            if (flags != null) admit(rows, flags, one, one)
        }
        var head: Rows? = null
        var previous: Rows? = null
        for (rows in replacement.values) {
            m.cancellation.checkpoint()
            if (previous == null) head = rows else previous.next = rows
            previous = rows
        }
        m.cancellation.checkpoint()
        if (head == null) headers.remove(scope) else headers[scope] = head
    }

    fun all(): Sequence<Pair<PremiseKey, Facts>> = sequence {
        m.cancellation.checkpoint()
        for ((header, rows) in allRows()) for ((shape, masks) in rows) for (id in masks.marks.ids) {
            m.cancellation.checkpoint()
            val mark = TaintMark(id)
            yield(markedInitial(header.initial, mark) to decode(header, shape, mark,
                if (mark in masks.protected) shape else null))
        }
    }

    fun borrow(premise: PremiseKey): Sequence<Facts> = sequence {
        m.cancellation.checkpoint()
        val initial = premise as? InitialAp ?: return@sequence
        val mark = (initial.mark as? MarkSlot.Concrete)?.mark ?: return@sequence
        val flow = flowInitialForCoverage(m, initial) ?: return@sequence
        for (scope in headers.keys) {
            m.cancellation.checkpoint()
            if (scope.initial !== flow) continue
            for ((header, rows) in scopedRows(scope)) {
                for ((shape, masks) in rows) {
                    m.cancellation.checkpoint()
                    if (mark in masks.marks) yield(decode(header, shape, mark,
                        if (mark in masks.protected) shape else null))
                }
            }
        }
    }

    /** Remove plain diagonal outputs covered by one complete typed FLOW row. */
    fun compact(flowInitial: InitialAp, flowFacts: FlowTree) {
        m.cancellation.checkpoint()
        if (!flowInitial.isFlow || (flowInitial.tail != Tail.STAR && flowInitial.tail != Tail.ANY) ||
            (flowFacts.tail != Tail.STAR && flowFacts.tail != Tail.ANY)) return
        for (layer in Layer.entries) {
            m.cancellation.checkpoint()
            if (flowFacts.layer == Layer.DEMAND && layer == Layer.NORMAL) continue
            val scope = Scope(flowInitial, flowFacts.base, layer)
            for ((header, rows) in scopedRows(scope).toList()) {
                if (header.tail != flowFacts.tail ||
                    (header.tail == Tail.STAR && !flowFacts.exclusion.isSubsetOf(header.exclusion))) continue
                for ((shape, masks) in rows.entries.toList()) {
                    m.cancellation.checkpoint()
                    val selected = m.intern((masks.marks - masks.protected) - flowFacts.markExclusion)
                    if (selected.isEmpty) continue
                    val rest = subtract(shape, flowFacts.root, header.tail)
                    if (rest === shape || rest == shape) continue
                    removeMark(rows, shape, masks, selected)
                    if (rest != null) admit(rows, rest, selected, MarkSet.EMPTY)
                }
                if (rows.isEmpty()) removeHeader(header)
            }
        }
    }

    private fun markedInitial(flow: InitialAp, mark: TaintMark): InitialAp =
        m.initial(flow.base, flow.path, flow.tail, flow.exclusion, MarkSlot.Concrete(mark))

    private fun removeMark(rows: MutableMap<FlowNode, Masks>, shape: FlowNode, masks: Masks, marks: MarkSet) {
        masks.marks = m.intern(masks.marks - marks)
        masks.protected = m.intern(masks.protected - marks)
        if (masks.marks.isEmpty) rows.remove(shape)
    }

    private fun admit(rows: MutableMap<FlowNode, Masks>, geometry: FlowNode, marks: MarkSet, protected: MarkSet) {
        val shape = interners.flow.internIfRequired(geometry)
        val masks = rows[shape]
        if (masks == null) rows[shape] = Masks(m.intern(marks), m.intern(protected))
        else {
            masks.marks = m.intern(masks.marks + marks)
            masks.protected = m.intern(masks.protected + protected)
        }
    }

    private fun union(a: FlowNode?, b: FlowNode?): FlowNode? = when {
        a == null -> b
        b == null -> a
        else -> FlowAlgebra.mergeAdd(a, b, m.cancellation)
    }

    private fun subtract(a: FlowNode, b: FlowNode, tail: Tail): FlowNode? =
        if (tail == Tail.STAR) subtractExact(a, b) else subtractCovered(a, b)

    private fun subtractCovered(a: FlowNode, b: FlowNode): FlowNode? = FlowAlgebra.subtract(a, b, FlowLeaf.NONE,
        at = { it }, below = { it }, cancellation = m.cancellation)

    private fun subtractExact(a: FlowNode, b: FlowNode): FlowNode? = FlowAlgebra.subtract(a, b, FlowLeaf.NONE,
        at = { it }, below = { FlowLeaf.NONE }, cancellation = m.cancellation)

    private class Frame<N>(val node: N, var next: Int = 0)

    /** Convert shape once; marks do not enter the geometry key. */
    private fun geometry(root: TaintNode): FlowNode {
        val memo = IdentityHashMap<TaintNode, FlowNode>()
        val stack = ArrayDeque<Frame<TaintNode>>()
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            m.cancellation.checkpoint()
            val frame = stack.peekLast()
            val kids = frame.node.childData
            if (kids != null && frame.next < kids.size) {
                val child = kids[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            memo[frame.node] = FlowAlgebra.node(if (frame.node.leaf.any.isEmpty) FlowLeaf.NONE else FlowLeaf.LEAF,
                frame.node.accessorData, kids?.map { memo.getValue(it) }?.toTypedArray())
            stack.removeLast()
        }
        return memo.getValue(root)
    }

    private fun scalar(root: FlowNode, mark: TaintMark): TaintNode {
        val memo = IdentityHashMap<FlowNode, TaintNode>()
        val stack = ArrayDeque<Frame<FlowNode>>()
        val leaf = m.taintLeaves(MarkSet.EMPTY, m.markSetOf(mark))
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            m.cancellation.checkpoint()
            val frame = stack.peekLast()
            val kids = frame.node.childData
            if (kids != null && frame.next < kids.size) {
                val child = kids[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            memo[frame.node] = m.taintAlg.node(if (frame.node.leaf.isEmpty) TaintLeaves.EMPTY else leaf,
                frame.node.accessorData, kids?.map { memo.getValue(it) }?.toTypedArray())
            stack.removeLast()
        }
        return memo.getValue(root)
    }

    private fun decode(header: Header, shape: FlowNode, mark: TaintMark, protected: FlowNode?): TaintTree =
        m.taintTree(header.base, header.layer, scalar(shape, mark), header.exclusion, anyTail = header.tail,
            nonSubsumable = protected?.let { scalar(it, mark) })

}

package org.opentaint.dataflow.bidi

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.fixtures.StoreFixtures
import kotlin.test.*

/** Incremental bridge checks, not a batch normal form or a confluence oracle.
 * Every trial restores the SAME current rows on both sides. Its DATA baseline
 * erases H, restores those rows without admission, and performs ONE no-H add.
 * This deliberately includes the selected DEMAND/ANY position law; the older
 * ReferenceTaintGroup compacts those positions and is not its oracle.
 *
 * H and guide expectations are independently decoded literal typed unions.
 * DATA observations enumerate f/g/h paths through depth 3 for full marks T/U;
 * they are finite spatial regions, not a universal STAR suffix-relation proof.
 * Explicit STAR/T4 and mixed-header witnesses supplement that bounded view.
 * This class does not establish all adapters, program recovery or global DATA
 * order independence. The production no-H path is the differential DATA
 * baseline, never the expected-H oracle.
 */
class ProtectedAdmissionDataBridgeTest {
    private val fixture = StoreFixtures()
    private val m = fixture.manager
    private val x = AccessPathBase.Argument(0)
    private val f = fixture.field("f")
    private val g = fixture.field("g")
    private val h = fixture.field("h")
    private val t = fixture.mark("T").id
    private val u = fixture.mark("U").id
    private val empty = ExclusionSet.Empty

    private data class Atom(val path: List<Int>, val exact: Boolean, val mark: Int)
    private fun exact(path: List<Int>, mark: Int = t) = Atom(path, true, mark)
    private fun span(path: List<Int>, mark: Int = t) = Atom(path, false, mark)
    private fun ex(vararg fields: Int) = ExclusionSet.of(fields)

    private class RawNode {
        val exact = sortedSetOf<Int>()
        val any = sortedSetOf<Int>()
        val children = sortedMapOf<Int, RawNode>()
    }

    private fun root(atoms: Set<Atom>): TaintNode {
        require(atoms.isNotEmpty())
        val root = RawNode()
        for (atom in atoms) {
            var node = root
            for (field in atom.path) node = node.children.getOrPut(field) { RawNode() }
            if (atom.exact) node.exact += atom.mark else node.any += atom.mark
        }
        fun build(node: RawNode): TaintNode = m.taintAlg.node(
            m.taintLeaves(MarkSet(node.exact.toIntArray()), MarkSet(node.any.toIntArray())),
            node.children.keys.toIntArray(), node.children.values.map(::build).toTypedArray())
        return build(root)
    }

    private fun tree(atoms: Set<Atom>, flags: Set<Atom> = emptySet(),
                     tail: Tail = Tail.STAR, e: ExclusionSet = empty,
                     layer: Layer = Layer.NORMAL): TaintTree {
        require(atoms.containsAll(flags))
        require(tail != Tail.ANY || e == empty)
        return m.taintTree(x, layer, root(atoms), e, tail,
            nonSubsumable = flags.takeIf { it.isNotEmpty() }?.let(::root))
    }

    /** Direct sparse-DAG inspection; no leaves(), covers(), subtraction,
     * canonicalizer or protection attachment is used to form expected keys. */
    private fun atoms(root: TaintNode?): Set<Atom> = buildSet {
        if (root == null) return@buildSet
        val todo = ArrayDeque<Pair<List<Int>, TaintNode>>()
        todo.addLast(emptyList<Int>() to root)
        while (todo.isNotEmpty()) {
            val (path, node) = todo.removeLast()
            node.leaf.exact.ids.forEach { add(exact(path, it)) }
            node.leaf.any.ids.forEach { add(span(path, it)) }
            val fields = node.accessors
            val children = node.children
            if (fields != null && children != null) for (i in fields.indices)
                todo.addLast((path + fields[i]) to children[i])
        }
    }

    private data class Key(val base: AccessPathBase, val layer: Layer,
                           val path: List<Int>, val mark: Int,
                           val tail: Tail, val e: ExclusionSet)

    private fun key(value: TaintTree, atom: Atom) = Key(value.base, value.layer,
        atom.path, atom.mark, if (atom.exact) Tail.EXACT else value.anyTail,
        if (atom.exact) empty else value.exclusion)

    private fun keys(values: List<TaintTree>, flags: Boolean = false): Set<Key> = buildSet {
        for (value in values) for (atom in atoms(if (flags) value.nonSubsumable else value.root))
            add(key(value, atom))
    }

    private fun guides(values: List<TaintTree>): Set<Key> = keys(values).filterTo(HashSet()) {
        it.layer == Layer.DEMAND && it.tail == Tail.ANY && it.e == empty
    }

    private data class Point(val base: AccessPathBase, val layer: Layer,
                             val path: List<Int>, val mark: Int)
    private val paths = buildList {
        var level = listOf(emptyList<Int>())
        addAll(level)
        repeat(3) {
            level = level.flatMap { p -> listOf(p + f, p + g, p + h) }
            addAll(level)
        }
    }

    /** Independent finite spatial denotation. Effective EXACT ignores mixed
     * wrapper E/tail; a span excludes only its first continuation field. */
    private fun region(values: List<TaintTree>): Set<Point> = buildSet {
        for (value in values) {
            val excluded = when (val e = value.exclusion) {
                ExclusionSet.Empty -> emptySet()
                is ExclusionSet.Concrete -> e.ids.toSet()
            }
            for (atom in atoms(value.root)) for (path in paths) {
                if (atom.exact) {
                    if (path == atom.path) add(Point(value.base, value.layer, path, atom.mark))
                } else if (path.size >= atom.path.size && path.take(atom.path.size) == atom.path &&
                    (path.size == atom.path.size || value.anyTail == Tail.ANY ||
                        path[atom.path.size] !in excluded)) {
                    add(Point(value.base, value.layer, path, atom.mark))
                }
            }
        }
    }

    private data class Observation(val after: List<TaintTree>, val delta: List<TaintTree>,
                                   val dataAfter: List<TaintTree>, val dataDelta: List<TaintTree>)

    private fun step(before: List<TaintTree>, offered: TaintTree, label: String): Observation {
        val protected = TaintGroup(m, m.newInterners().taint)
        val noH = TaintGroup(m, m.newInterners().taint)
        for (current in before) {
            protected.restoreCurrent(current)
            noH.restoreCurrent(current.withoutProtection())
        }
        val dataDelta = noH.addAll(offered.withoutProtection())
        val dataAfter = noH.all().toList()
        val delta = protected.addAll(offered)
        val after = protected.all().toList()

        val beforeRegion = region(before)
        val afterRegion = region(after)
        assertEquals(region(dataAfter), afterRegion, "$label: same restored-state DATA result")
        assertEquals(region(dataDelta) - beforeRegion, region(delta) - beforeRegion,
            "$label: same new DATA region; whole-content deltas may replay old content")
        assertEquals(afterRegion, region(before + delta), "$label: complete DATA delta")
        assertTrue(afterRegion.containsAll(region(delta)), "$label: no delta outside retained DATA")

        val oldH = keys(before, flags = true)
        val expectedH = oldH + keys(listOf(offered), flags = true)
        val actualH = keys(after, flags = true)
        val deltaH = keys(delta, flags = true)
        assertEquals(expectedH, actualH, "$label: literal typed H union")
        assertTrue(expectedH.containsAll(deltaH), "$label: no invented delta H")
        assertEquals(expectedH, oldH + deltaH, "$label: complete typed H delta")

        val oldGuides = guides(before)
        val expectedGuides = oldGuides + guides(listOf(offered))
        assertEquals(expectedGuides, guides(after), "$label: literal selected MAY position union")
        assertTrue(expectedGuides.containsAll(guides(delta)), "$label: no invented guide delta")
        assertEquals(expectedGuides, oldGuides + guides(delta), "$label: complete guide delta")

        for (value in after + delta) assertTrue(atoms(value.root).containsAll(atoms(value.nonSubsumable)),
            "$label: every H bit has a literal same-packet DATA carrier")
        assertEquals(after.size, after.map { it.groupKey }.toSet().size, "$label: unique typed headers")
        return Observation(after, delta, dataAfter, dataDelta)
    }

    private fun sequence(offers: List<TaintTree>, label: String): List<Observation> {
        var current = emptyList<TaintTree>()
        return offers.mapIndexed { i, offered ->
            step(current, offered, "$label/$i").also { current = it.after }
        }
    }

    @Test fun `STAR T4 E weakening keeps the whole mixed-content delta with either H arrival order`() {
