package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor

/** One run's pure C2 policy. Image tests inspect templates; they never intern hypothetical facts. */
class RestrictedInitialPolicy(
    val run: Int = 2,
    val fieldLimit: Int = Int.MAX_VALUE,
    val direction: Direction = if (run % 2 == 0) Direction.BACKWARD else Direction.FORWARD,
    private val catalog: MarkTable? = null,
) {
    init { require(run >= 2 && fieldLimit >= 1) }

    fun emit(demand: Pattern, actual: Pattern): Pattern? {
        if (!validDemand(demand)) return null
        val d = normalizeDemandFieldExclusion(demand)
        if (d.fact.base != actual.fact.base || !markSub(d.fact.mark, actual.fact.mark, catalog)) return null
        if (d.fact.base == AccessPathBase.Zero && !canonicalZero(actual)) return null
        if (!fitsBudget(d) || !fitsBudget(actual)) return null
        // Only a concrete MAY witness can supply a provisional exact data point.
        if (d.fact.tail == Tail.EXACT && actual.fact.tail == Tail.ANY && d.fact.mark is MarkSlot.Star) return null
        val p = d.fact.path
        val q = actual.fact.path
        val mark = boundMark(d.fact.mark, actual.fact.mark)
        fun result(path: List<Int>, tail: Tail, e: ExclusionSet = ExclusionSet.Empty): Pattern? {
            val value = Pattern(PathFact(d.fact.base, path, tail, mark), e)
            return value.takeIf(::legalInitial)
        }
        if (q == p) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.STAR -> null
                Tail.EXACT -> result(p, Tail.EXACT)
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, actual.exclusion)
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null // A demand entry never has a MUST tail.
        }
        if (q.startsWith(p)) {
            if (!d.tailAdmits(q.drop(p.size))) return null
            return when (d.fact.tail) {
                Tail.STAR -> if (run == 2) result(p, Tail.STAR, d.exclusion) else null
                Tail.ANY -> {
                    val end = firstFieldEnd(d.fact.base, p, q) ?: return null
                    val tail = if (mark is MarkSlot.Concrete && actual.fact.tail == Tail.EXACT && end == q.size)
                        Tail.EXACT else Tail.STAR
                    result(q.take(end), tail)
                }
                else -> null
            }
        }
        if (p.startsWith(q) && actual.tailAdmits(p.drop(q.size))) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, d.exclusion)
                else -> null
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null
        }
        return null
    }

    /** Preserve concrete support without interning an AP. Actuals are legal ApOps.leaves views:
     * exact concrete leaves have Empty E even in a mixed tree; MAY headers also have Empty E. */
    fun emitAdmission(demand: Pattern, actual: Pattern, actualLayer: Layer): InitialEmission? {
        val emitted = emit(demand, actual) ?: return null
        return InitialEmission(emitted, admissionLayer(emitted, actual, actualLayer))
    }

    /** Complete structural output image, including the non-idempotent run-2 requested STAR. */
    fun canEmitInitial(demand: Pattern, initial: Pattern): Boolean {
        if (!validDemand(demand)) return false
        val d = normalizeDemandFieldExclusion(demand)
        if (!legalInitial(initial) || !fitsBudget(d) || d.fact.base != initial.fact.base ||
            !renderedMark(d.fact.mark, initial.fact.mark)) return false
        val p = d.fact.path
        val q = initial.fact.path
        if (q == p) return when (initial.fact.tail) {
            Tail.EXACT -> initial.exclusion == ExclusionSet.Empty && d.fact.tail != Tail.ANY_TAINT
            Tail.ANY -> d.fact.tail == Tail.ANY && initial.exclusion == ExclusionSet.Empty
            Tail.ANY_TAINT -> d.fact.tail == Tail.ANY
            Tail.STAR -> run == 2 && d.fact.tail == Tail.STAR && initial.exclusion == d.exclusion &&
                p.count { it.isCounted() } < fieldLimit &&
                !(initial.fact.base == STATIC && p.size == 1)
        }
        if (d.fact.tail != Tail.ANY || !q.startsWith(p) || !d.tailAdmits(q.drop(p.size))) return false
        val end = firstFieldEnd(d.fact.base, p, q) ?: return false
        return end == q.size && initial.exclusion == ExclusionSet.Empty &&
            (initial.fact.tail == Tail.STAR || initial.fact.tail == Tail.EXACT && initial.fact.mark is MarkSlot.Concrete)
    }

    /** Summary keys are normalized, but the containment test belongs to their raw preimage. */
    fun canStoreInitial(entry: Pattern, stored: Pattern): Boolean {
        if (!validDemand(entry)) return false
        fun fits(raw: Pattern): Boolean = canEmitInitial(entry, raw) && insideDemand(raw, entry, catalog)
        if (fits(stored)) return true
        return stored.fact.mark is MarkSlot.Star && stored.fact.tail == Tail.STAR &&
            stored.exclusion == ExclusionSet.Empty && fits(stored.copy(fact = stored.fact.copy(tail = Tail.EXACT)))
    }

    private fun boundMark(required: MarkSlot, actual: MarkSlot): MarkSlot =
        if (required is MarkSlot.Concrete && catalog?.isGroup(required.mark) == true &&
            actual is MarkSlot.Concrete) actual else required

    private fun renderedMark(required: MarkSlot, rendered: MarkSlot): Boolean =
        if (required is MarkSlot.Star) rendered == required
        else rendered is MarkSlot.Concrete && markSub(required, rendered, catalog)

    private fun fitsBudget(p: Pattern): Boolean = p.fact.path.count { it.isCounted() } <= fieldLimit

    private fun validDemand(p: Pattern): Boolean =
        !(p.fact.tail == Tail.EXACT && p.fact.mark is MarkSlot.Concrete && p.exclusion != ExclusionSet.Empty) &&
            (p.fact.base != AccessPathBase.Zero || canonicalZero(p))

    private fun canonicalZero(p: Pattern): Boolean = p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
        p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)

    private fun legalInitial(p: Pattern): Boolean {
        if (!fitsBudget(p) || p.fact.tail == Tail.ANY_TAINT && direction == Direction.BACKWARD) return false
        if (p.fact.mark is MarkSlot.Concrete && catalog?.isGroup(p.fact.mark.mark) == true) return false
        if (p.fact.tail != Tail.STAR && p.fact.tail != Tail.ANY_TAINT && p.exclusion != ExclusionSet.Empty) return false
        if (p.fact.mark is MarkSlot.Star && !p.fact.mark.excluded.isEmpty) return false
        if (p.fact.base == AccessPathBase.Zero) return p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
            p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)
        if (p.fact.base != STATIC || p.fact.mark is MarkSlot.Star) return true
        val path = p.fact.path
        return path.size == 1 && path[0].isClass() && p.fact.tail == Tail.EXACT ||
            path.size >= 2 && path[0].isClass() && path[1].isFieldAccessor()
    }

    /** A JVM static anchor is indivisible. A raw array element cannot become a class abstraction. */
    private fun firstFieldEnd(base: AccessPathBase, prefix: List<Int>, path: List<Int>): Int? {
        val index = (prefix.size until path.size).firstOrNull { path[it].isCounted() } ?: return null
        val end = index + 1
        if (base == STATIC && (end < 2 || !path[0].isClass() || !path[1].isFieldAccessor())) return null
        return end
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** The two annotations of a TAINT leaf and the single annotation of a FLOW flag. */
private class SummaryTails<P : TrieLeaf>(
    val exclusion: ExclusionSet,
    val anyExclusion: ExclusionSet = ExclusionSet.Empty,
    val select: (P, star: Boolean, any: Boolean, exact: Boolean) -> P,
)

private fun flowTails(a: FlowTree) = SummaryTails<FlowLeaf>(
    if (a.tail == Tail.STAR) a.exclusion else ExclusionSet.Empty,
    if (a.tail == Tail.ANY_TAINT) a.exclusion else ExclusionSet.Empty,
) { p, star, any, exact ->
    val selected = when (a.tail) {
        Tail.STAR -> star
        Tail.EXACT -> exact
        Tail.ANY, Tail.ANY_TAINT -> any
    }
    if (selected) p else FlowLeaf.NONE
}

private fun taintTails(m: ApManager, a: TaintTree) =
    if (a.anyTail == Tail.STAR) SummaryTails<TaintLeaves>(a.exclusion) { p, star, _, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (star) p.any else MarkSet.EMPTY)
    } else SummaryTails<TaintLeaves>(ExclusionSet.Empty, a.exclusion) { p, _, any, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (any) p.any else MarkSet.EMPTY)
    }

/** Preserve full selected leaves and their input annotations. Record demotion occurs after return actions. */
internal fun satisfyingPart(m: ApManager, a: Facts, j: Pattern, mode: ApMode, record: Boolean): Facts? {
    m.cancellation.checkpoint()
    if (a.base != j.fact.base) return null
    check(j.fact.tail != Tail.ANY_TAINT || (mode.restricted && mode.direction == Direction.FORWARD)) {
        "W8 (c): a must-premise is forward restricted"
    }
    val below = record || mode.run1 || (mode.restricted && (j.fact.mark is MarkSlot.Star || j.fact.tail == Tail.STAR))
    val inside = record || mode.restricted || mode.run1
    if (j.fact.tail == Tail.ANY_TAINT && j.fact.mark is MarkSlot.Star) return when (a) {
        is Reach -> null
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star || a.tail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, FlowAlgebra, a.exclusion, j) { it }
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> if (a.anyTail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, m.taintAlg, a.exclusion, j) {
                m.taintLeaves(MarkSet.EMPTY, it.any)
            }?.let { markSubPart(m, it, j, mode) }
                ?.let { m.taintTree(a.base, a.layer, it, a.exclusion, a.anyTail) }
    }
    return when (a) {
        is Reach -> a.takeIf { j.fact.base == AccessPathBase.Zero }
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star) null
            else summaryPart(m, a.root, FlowAlgebra, flowTails(a), j, below, inside)
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> summaryPart(m, a.root, m.taintAlg, taintTails(m, a), j, below, inside)
            ?.let { markSubPart(m, it, j, mode) }
            ?.let { m.taintTree(a.base, if (mode.markMode == MarkMode.GROUP) Layer.DEMAND else a.layer, it, a.exclusion, a.anyTail) }
    }
}

/** A uniform query requires an actual uniform scope that covers the entire query. */
private fun <P : TrieLeaf> definiteMustPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, exclusion: ExclusionSet,
    j: Pattern, onlyMust: (P) -> P,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val at = root.walk(path) { depth, node ->
        m.cancellation.checkpoint()
        spine += if (exclusion.admits(path[depth])) onlyMust(node.leaf) else alg.empty
    }
    if (at != null) spine += if (exclusion.isSubsetOf(j.exclusion)) onlyMust(at.leaf) else alg.empty
    return alg.chain(m, path, spine)
}

private fun markSubPart(m: ApManager, n: TaintNode, j: Pattern, mode: ApMode): TaintNode? {
    val gate = MarkGate(m, j.fact.mark, MarkSlot.STAR, mode)
    return m.taintAlg.mapLeaves(n, m.cancellation) { p ->
        m.taintLeaves(gate.taintMarks(p.exact) ?: MarkSet.EMPTY, gate.taintMarks(p.any) ?: MarkSet.EMPTY)
    }
}

private fun <P : TrieLeaf> summaryPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
    below: Boolean, inside: Boolean,
): TrieNode<P>? {
    val b = if (below) applicablePart(m, root, alg, t, j) else null
    val i = if (inside) insidePart(m, root, alg, t, j) else null
    return if (b == null) i else if (i == null) b else alg.mergeAdd(b, i, m.cancellation)
}

private fun <P : TrieLeaf> applicablePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val u = root.walk(path) { _, _ -> m.cancellation.checkpoint() } ?: return null
    m.cancellation.checkpoint()
    val ej = j.exclusion
    val anyAt = ej.isSubsetOf(t.anyExclusion)
    val at = when (j.fact.tail) {
        Tail.STAR -> t.select(u.leaf, ej.isSubsetOf(t.exclusion), anyAt, true)
        Tail.EXACT -> t.select(u.leaf, false, false, true)
        Tail.ANY_TAINT -> t.select(u.leaf, false, anyAt, false)
        Tail.ANY -> t.select(u.leaf, false, true, false)
    }
    val kids = when (j.fact.tail) {
        Tail.STAR -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
        Tail.EXACT -> null
        Tail.ANY_TAINT -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
        Tail.ANY -> alg.retainChildren(u, m.cancellation) { true }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
    }
    return alg.withLeaf(kids, at)?.let { alg.prepend(m, m.path(path), it) }
}

private fun <P : TrieLeaf> insidePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val u = root.walk(path) { d, n ->
        m.cancellation.checkpoint()
        spine += t.select(n.leaf, t.exclusion.admits(path[d]), t.anyExclusion.admits(path[d]), false)
    }
    m.cancellation.checkpoint()
    if (u != null) spine += t.select(u.leaf,
        when (j.fact.tail) {
            Tail.EXACT -> true
            Tail.STAR -> t.exclusion.isSubsetOf(j.exclusion)
            Tail.ANY, Tail.ANY_TAINT -> t.exclusion == ExclusionSet.Empty
        },
        j.fact.tail == Tail.EXACT || t.anyExclusion.isSubsetOf(j.exclusion),
        j.fact.tail == Tail.EXACT)
    return alg.chain(m, path, spine)
}

/** One edge for each tail/mark kind, followed by a graft into every path having that kind. */
internal fun applySummaryPart(ops: ApOps, a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    check(a !is FlowTree || g is FlowTree) { "a FLOW fact satisfies only a `*` premise, whose summaries are FLOW" }
    for (kind in leafKinds(m, g, j)) {
        m.cancellation.checkpoint()
        val one = CollectingOut()
        ops.applyCompiledEdge(a, kind.edge, g.layer == Layer.DEMAND, -1, mode, one)
        // F78: applying an excluded abstract target preserves the interest on
        // the caller's original slot before publishing its excluded result.
        for (mark in one.markRequests) {
            m.cancellation.checkpoint()
            out.markRequest(mark)
        }
        for (r in one.results) {
            m.cancellation.checkpoint()
            out.result(kind.graft(r))
        }
    }
}

/** A transient native record uses its Pattern directly, retaining its own exclusions. */
internal fun applyRecordLeafPart(ops: ApOps, a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                                 mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    val edge = ops.compiled(summaryEdge(view.premise, view.result))
    val one = CollectingOut()
    ops.applyCompiledEdge(a, edge, view.result.demand, -1, mode, one)
    for (mark in one.markRequests) {
        m.cancellation.checkpoint()
        out.markRequest(mark)
    }
    for (r in one.results) {
        m.cancellation.checkpoint()
        out.result(if (nonSubsumable) m.selectedProtection(r, null) else r)
    }
}

private class SummaryLeafKind(val edge: CompiledEdge, val graft: (Facts) -> Facts)

private fun leafKinds(m: ApManager, g: Facts, j: InitialAp): List<SummaryLeafKind> {
    val jOwn = j.tail == Tail.ANY_TAINT
    val inputShared = if (jOwn) ExclusionSet.Empty else j.exclusion
    fun edge(tail: Tail, mark: MarkSlot, exclusion: ExclusionSet, toExclusion: ExclusionSet = ExclusionSet.Empty) =
        CompiledEdge(j.base, j.pathData, j.tail, j.mark, g.base, null, tail, mark,
            m.intern(exclusion),
            m.intern(if (jOwn) j.exclusion else ExclusionSet.Empty), m.intern(toExclusion))
    return when (g) {
        is Reach -> listOf(SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(TaintMark.ZERO), ExclusionSet.Empty)) { it })
        is FlowTree -> listOf(SummaryLeafKind(edge(g.tail, MarkSlot.Star(g.markExclusion),
            if (g.tail == Tail.STAR || g.tail == Tail.EXACT) inputShared.union(g.exclusion) else inputShared,
            if (g.tail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty)) {
            graftSummary(m, g.root, { p -> p == FlowLeaf.LEAF }, it)
        })
        is TaintTree -> {
            val all = m.taintAlg.foldAll(g.root, m.cancellation)
            val anyTail = g.anyTail
            val kinds = ArrayList<SummaryLeafKind>()
            for (id in all.exact.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                kinds += SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(mark), inputShared)) {
                    graftSummary(m, g.root, { p -> mark in p.exact }, it)
                }
            }
            for (id in all.any.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                val shared = if (anyTail == Tail.STAR) inputShared.union(g.exclusion) else inputShared
                val own = if (anyTail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty
                kinds += SummaryLeafKind(edge(anyTail, MarkSlot.Concrete(mark), shared, own)) {
                    graftSummary(m, g.root, { p -> mark in p.any }, it)
                }
            }
            kinds
        }
    }
}

private fun <G : TrieLeaf> graftSummary(m: ApManager, g: TrieNode<G>, occurs: (G) -> Boolean, r: Facts): Facts =
    when (r) {
        is Reach -> r
        is FlowTree -> r.withRoot(checkNotNull(FlowAlgebra.graft(g, occurs, r.root, m.cancellation)))
        is TaintTree -> m.taintTree(r.base, r.layer,
            checkNotNull(m.taintAlg.graft(g, occurs, r.root, m.cancellation)), r.exclusion, r.anyTail,
            r.nonSubsumable?.let { m.taintAlg.graft(g, occurs, it, m.cancellation) })
    }

/** Matching is supplied by the caller. W7 makes each complete concrete member return the same target. */
internal fun applyCombinationPart(
    manager: ApManager, parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(parts.size >= 2)
    val layers = ArrayList<Layer>(parts.size)
    for ((part, _) in parts) {
        manager.cancellation.checkpoint()
        check(part is TaintTree)
        layers += part.layer
    }
    applyMatchedCombinationPart(manager, layers, g, out)
}

/** E6's full member matcher has checked TAINT inputs. Their roots do not affect this transfer. */
internal fun applyMatchedCombinationPart(
    manager: ApManager, linkLayers: List<Layer>, g: TaintTree, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(linkLayers.size >= 2)
    var layer = g.layer
    for (linkLayer in linkLayers) {
        manager.cancellation.checkpoint()
        if (linkLayer == Layer.DEMAND) layer = Layer.DEMAND
    }
    out.result(g.withLayer(layer))
}

/** Remove identical annotated leaves; preserve the other leaves without record demotion. */
internal fun withoutPart(manager: ApManager, c: Facts, part: Facts): Facts? {
    manager.cancellation.checkpoint()
    return when {
        c.base != part.base -> c
        c is TaintTree && part is TaintTree ->
            if (c.layer != part.layer || (part.root.hasAny &&
                    (part.exclusion != c.exclusion || part.anyTail != c.anyTail))) c
            else manager.taintAlg.minusNode(c.root, part.root, manager.cancellation)
                ?.let { if (it === c.root) c else c.withRoot(it) }
        c.groupKey != part.groupKey -> c
        c is Reach -> if (part is Reach && part.layer == c.layer) null else c
        c is FlowTree && part is FlowTree -> FlowAlgebra.minusNode(c.root, part.root, manager.cancellation)
            ?.let { if (it === c.root) c else c.withRoot(it) }
        else -> c
    }
}

package org.opentaint.dataflow.bidi.ap


/** Shared facade. All walk state is local to the call. */
class ApOps(val manager: ApManager) {
    fun run1Cover(f: Facts, emit: (Facts) -> Unit) = run1CoverFacts(manager, f, emit)

    /** Scalar callers must not silently demote exact members of a mixed group. */
    fun run1Cover(f: Facts): Facts {
        var only: Facts? = null
        run1Cover(f) { value -> check(only == null) { "Mixed E-bearing facts require the callback cover" }; only = value }
        return checkNotNull(only)
    }
    fun applyEdge(c: Facts, premise: PremiseKey, e: PathEdge, statementEdge: Boolean,
                  mode: ApMode, out: ApOut, may: Boolean = false,
                  unchangedStaticInitial: InitialAp? = null, ruleAssignment: Boolean = false) {
        check(unchangedStaticInitial == null ||
            (unchangedStaticInitial === premise && unchangedStaticInitial.manager === manager)) {
            "The ordinary static gate needs this edge's original initial"
        }
        val ce = compiled(e)
        val from = (e.from.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val assigned = (e.to.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val protect = ruleAssignment && from != null && assigned != null &&
            (from == assigned || premise.members.any {
                (it.mark as? MarkSlot.Concrete)?.mark?.let { atom -> manager.marks.runtimeAtom(atom, mode.markMode) } == assigned && from != assigned
            })
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, manager.markSetOf(assigned!!)))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyCompiledEdge(c, ce, may, staticIdentityDepth(c, premise, ce, statementEdge, mode), mode, sink,
            unchangedStaticInitial)
    }

    internal fun compiled(e: PathEdge): CompiledEdge {
        val old = e.compiled
        if (old != null && (old.toPath == null || old.toPath.manager === manager)) return old
        return manager.compile(e).also { e.compiled = it }
    }

    internal fun applyCompiledEdge(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                   staticAt: Int, mode: ApMode, out: ApOut,
                                   unchangedStaticInitial: InitialAp? = null) {
        manager.transportProtection(c, out) { part, sink ->
            applyCompiledEdgeRaw(part, ce, edgeDemand, staticAt, mode, sink, unchangedStaticInitial)
        }
    }

    private fun applyCompiledEdgeRaw(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                    staticAt: Int, mode: ApMode, out: ApOut,
                                    unchangedStaticInitial: InitialAp?) {
        manager.cancellation.checkpoint()
        if (c.base != ce.fromBase) return
        val sink = out.run1Policy(manager, mode)
        val app = EdgeApplication(manager, ce, edgeDemand, mode, sink, unchangedStaticInitial)
        when (c) {
            is Reach -> app.reach(c)
            is FlowTree -> app.flow(c, staticAt)
            is TaintTree -> app.taint(c)
        }
        app.results.flush(sink)
    }

    fun satisfying(a: Facts, j: InitialAp, mode: ApMode, record: Boolean = false): Facts? =
        satisfying(a, j.toPattern(), mode, record)

    fun satisfying(a: Facts, j: Pattern, mode: ApMode, record: Boolean = false): Facts? =
        satisfyingPart(manager, a, j, mode, record)?.let { retainProtection(a, it, manager.cancellation) }

    fun applySummary(a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut,
                     original: PremiseKey? = null) {
        val masks = (g as? TaintTree)?.protectedPart()?.let { protected ->
            ProtectionOutputs(manager).also { applySummaryPart(this, a.withoutProtection(), j, protected, mode, it) }
        }
        val incoming = (j.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && incoming != null) {
            for (i in original.members) {
                val origin = (i.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
                if (origin != incoming) restored += origin
            }
        }
        val restoredMarks = manager.intern(restored)
        val sink = if (masks == null && restoredMarks.isEmpty) out else object : ApOut {
            override fun result(f: Facts) {
                val flagged = masks?.attach(f) ?: f
                out.result(if (restoredMarks.isEmpty) flagged else manager.selectedProtection(flagged, restoredMarks))
            }
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applySummaryPart(this, a, j, g, mode, sink)
    }

    fun applyRecordLeaf(a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                        mode: ApMode, out: ApOut, original: PremiseKey? = null) {
        val trigger = (view.premise.fact.mark as? MarkSlot.Concrete)?.mark
            ?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && trigger != null) for (i in original.members) {
            val origin = (i.mark as? MarkSlot.Concrete)?.mark
                ?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
            if (origin != trigger) restored += origin
        }
        val sink = if (restored.isEmpty) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, restored))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyRecordLeafPart(this, a, view, nonSubsumable, mode, sink)
    }

    fun applyCombination(parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut) =
        applyCombinationPart(manager, parts, g, mode, out.run1Policy(manager, mode))

    /** Used only after E6's full matching and TAINT guards. Caller layers remain in the resume context. */
    internal fun applyMatchedCombination(linkLayers: List<Layer>, g: TaintTree, out: ApOut) =
        applyMatchedCombinationPart(manager, linkLayers, g, out)

    fun without(c: Facts, part: Facts): Facts? = withoutPart(manager, c, part)
    fun reverse(e: PathEdge): PathEdge? = revEdge(e)
    fun leaves(f: Facts): Sequence<Pattern> = leafViews(manager, f)
    fun leavesNear(f: Facts, p: IntArray): Sequence<Pattern> = nearLeafViews(manager, f, p)

    fun clean(c: Facts, premise: PremiseKey, cl: Cleaner, mode: ApMode, out: ApOut) {
        val protect = c.base == cl.base
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, cl.mark?.let { manager.markSetOf(manager.marks.runtimeAtom(it, mode.markMode)) }))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        manager.transportProtection(c, sink) { part, target ->
            cleanFacts(manager, part, premise, cl, mode, target.run1Policy(manager, mode))
        }
    }

    /** Selected FULL mask; null Cleaner.mark retains its all-mark meaning on the scalar API. */
    fun cleanSelectedFullMask(c: Facts, premise: PremiseKey, geometry: Cleaner, selected: MarkSet,
                              mode: ApMode, request: (MarkSet) -> Unit, out: ApOut) {
        check(geometry.mark != null) { "A FULL cleanup block must have selected-mark geometry" }
        val sink = if (c.base != geometry.base) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, selected))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        val protected = (c as? TaintTree)?.protectedPart()
        val masks = protected?.let { part -> ProtectionOutputs(manager).also {
            cleanSelectedFullMask(manager, part, geometry, selected, mode, {}, it.run1Policy(manager, mode))
        } }
        val target = if (masks == null) sink else object : ApOut {
            override fun result(f: Facts) = sink.result(masks.attach(f))
            override fun markRequest(mark: TaintMark) = sink.markRequest(mark)
        }
        cleanSelectedFullMask(manager, c, geometry, selected, mode, request, target.run1Policy(manager, mode))
    }

    fun filter(c: Facts, f: TypeFilter): Facts? = filterFacts(manager, c, f)?.let { retainProtection(c, it, manager.cancellation) }
    fun limit(c: Facts, fieldLimit: Int, out: ApOut) = manager.transportProtection(c, out) { part, sink ->
        limitFacts(manager, part, fieldLimit, sink)
    }
    /** Pass the original initial only when the run-1 static catalog covers this check. */
    fun checkMark(c: Facts, p: Pattern, mode: ApMode,
                  unchangedStaticInitial: InitialAp? = null): MarkCheck =
        when (val result = markCheckFacts(manager, c, p, mode, unchangedStaticInitial)) {
            is MarkCheck.Holds -> MarkCheck.Holds(retainProtection(c, result.facts, manager.cancellation))
            else -> result
        }
    fun withoutMarks(c: Facts, marks: MarkSet): Facts? = withoutMarksPart(manager, c, marks)

    fun targetTree(target: PathFact, layer: Layer, mode: ApMode? = null): Facts {
        check(target.mark is MarkSlot.Concrete && target.tail != Tail.STAR) { "W7: a target must be concrete and exact or any" }
        val value = manager.factsOf(target, ExclusionSet.Empty, layer)
        return if (mode == null) value else manager.runtimeFact(value, mode)
    }

    fun zero(layer: Layer): Reach = Reach.of(layer)
    fun startFact(i: InitialAp): Facts = initialFacts(manager, i)
    fun startFact(i: InitialAp, mode: ApMode): Facts = manager.runtimeFact(initialFacts(manager, i), mode)
    fun runtimeFact(f: Facts, mode: ApMode): Facts = manager.runtimeFact(f, mode)
    fun policy(added: Facts): InitialAp = policyInitial(manager, added)
    fun emit(d: DemandPattern, added: Facts, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<InitialAp> = emitInitials(this, d, added, policy)
    fun restrictReference(j: InitialAp, g: Facts, d: DemandPattern): List<Conclusion> = restrictRaw(this, j, g, d)
    fun restrict(j: InitialAp, g: Facts, d: DemandPattern, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<Facts> = restrictFacts(this, j, g, d, policy)
    fun demandPart(premise: PremiseKey, g: Facts, direction: Direction): Facts? =
        selectDemand(manager, premise, g, direction)
}

private fun staticIdentityDepth(c: Facts, premise: PremiseKey, ce: CompiledEdge,
                                statementEdge: Boolean, mode: ApMode): Int {
    if (c !is FlowTree || c.layer != Layer.NORMAL || !mode.run1 || !statementEdge) return -1
    if (c.base != STATIC || ce.fromBase != STATIC) return -1
    val i = premise as? InitialAp ?: return -1
    if (i.base != STATIC || i.tail != Tail.STAR || i.mark != MarkSlot.STAR) return -1
    val q = i.pathData
    if (!(q.isEmpty() || (q.size == 1 && q[0].isClass()))) return -1
    if (ce.fromPathData.size <= q.size || !ce.fromPathData.startsWith(q)) return -1
    return q.size
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.store.AddedFactAccumulator
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.ConjunctionStore
import org.opentaint.dataflow.bidi.store.NdBinding
import org.opentaint.dataflow.bidi.store.KaryJoin
import org.opentaint.dataflow.bidi.store.Record
import org.opentaint.ir.api.common.cfg.CommonCallExpr
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.ArrayDeque

/** Call walks and suspended return batches belong to one method actor. */
class RunMethodCallServices(core: BlockRunState) : MethodCallServices {
    private var owner: BlockRunState? = core
    // Keep semantic unresolved observations once per qualified current input.
    private var observed: AddedFactAccumulator? = if (core.config.run1) AddedFactAccumulator(core.ap) else null

    private fun active(): BlockRunState = checkNotNull(owner) { "The call services were released" }.also {
        it.ap.cancellation.checkpoint()
    }

    private data class PlanFact(val premise: PremiseKey, val facts: Facts, val identityCandidate: Boolean?)
    private fun planFact(premise: PremiseKey, facts: Facts, identity: Boolean?) =
        PlanFact(premise, facts, identity)
    /** One cleaner step owns this collection. Ordinary identity stays unchanged;
     * equal results must OR their annotation before the next step sees them. */
    private class PlanFacts(private val ap: ApManager) : AbstractMutableCollection<PlanFact>() {
        private val values = LinkedHashMap<PlanFact, PlanFact>()
        override val size: Int get() = values.size
        override fun iterator(): MutableIterator<PlanFact> = values.values.iterator()
        override fun add(element: PlanFact): Boolean {
            if (!RuntimeDataDomain.packet(element.premise, element.facts)) return false
            val old = values[element]
            if (old == null) {
                values[element] = element
                return true
            }
            val (merged, delta) = ap.mergeAddDelta(old.facts, element.facts)
            if (delta == null) return false
            values[element] = element.copy(facts = merged)
            return true
        }
    }
    private class CallContext(val node: CommonInst, val call: CommonCallExpr, val plan: CallPlan, val callerLayer: Layer)
    private class Frame(val point: CallPoint, val facts: List<PlanFact>, val pendingDemotion: Boolean) {
        var entered = false
        var next = 0
        var triggers = Triggers.NONE
    }
    private val CallPlan.callees: CallStage.Callees?
        get() = stages.firstNotNullOfOrNull { it as? CallStage.Callees }

    override fun process(item: EdgeDelta) {
        val core = active()
        if (!RuntimeDataDomain.packet(item.premise, item.facts)) return
        val call = checkNotNull(core.context.callAt(item.node)) { "The delta is not at a call" }
        core.forms.withCall(core.key, item.node, call) { plan ->
            val ctx = CallContext(item.node, call, plan, item.facts.layer)
            when {
                item.facts is Reach -> zeroAtCall(item, ctx)
                item.facts.base !in ctx.plan.touched -> core.emitUnchanged(item)
                else -> flow(ctx, ctx.plan.entry, listOf(planFact(item.premise, item.facts, null)))
            }
        }
    }

    /** An explicit frame stack preserves stage order and keeps pending demotion local to this invocation. */
    private fun flow(ctx: CallContext, point: CallPoint, facts: List<PlanFact>, pendingDemotion: Boolean = false) {
        val core = active()
        check(!pendingDemotion || core.forward) { "Native must-record demotion is only forward" }
        val valid = facts.filter { RuntimeDataDomain.packet(it.premise, it.facts) }
        if (valid.isEmpty()) return
        val stack = ArrayDeque<Frame>()
        stack.addLast(Frame(point, valid, pendingDemotion))
        while (stack.isNotEmpty()) {
            core.ap.cancellation.checkpoint()
            val frame = stack.peekLast()
            if (!frame.entered) {
                frame.entered = true
                if (frame.point == ctx.plan.exit) {
                    for (fact in frame.facts) {
                        core.ap.cancellation.checkpoint()
                        val result = if (frame.pendingDemotion) toDemand(fact.facts) else fact.facts
                        core.cut(Cut.CALL, fact.premise, result) { premise, cut -> core.emitAfter(premise, ctx.node, cut) }
                    }
                    stack.removeLast()
                    continue
                }
                if (core.forward && frame.point == CallPoint.BOUND) {
                    for (fact in frame.facts) {
                        core.ap.cancellation.checkpoint()
                        val ordinal = ctx.plan.stages.indexOfFirst { it.from == frame.point }.coerceAtLeast(0)
                        frame.triggers += core.localServices.checkSinksAt(fact.premise, ctx.node, fact.facts, ctx.plan.sinks,
                            OperationInput(ResumeSite.CallStageInput(core.operation(ctx.node, ordinal)), fact.premise, fact.facts,
                                CallResumeState(ctx.callerLayer, fact.identityCandidate, frame.pendingDemotion)))
                    }
                }
                if (core.config.run1 && frame.point == CallPoint.ADDED) observeUnresolved(ctx, frame.facts)
            }
            val stages = ctx.plan.stagesAt(frame.point)
            if (frame.next >= stages.size) { stack.removeLast(); continue }
            val stage = stages[frame.next++]
            val out = applyStage(ctx, stage, frame.facts, frame.triggers, frame.pendingDemotion)
            if (out.isNotEmpty()) stack.addLast(Frame(stage.to, out, frame.pendingDemotion))
        }
    }

    private fun applyStage(ctx: CallContext, stage: CallStage, facts: List<PlanFact>, triggers: Triggers,
                           pendingDemotion: Boolean = false): List<PlanFact> {
        val core = active()
        val out = ArrayList<PlanFact>()
        val ordinal = ctx.plan.stages.indexOf(stage)
        when (stage) {
            is CallStage.Edges -> {
                if (stage.kind == StageKind.END_FACTS) return emptyList() // ignored in every run
                val guard = if (core.forward) stage.guard else null
                if (guard is Guard.SinkTriggered) {
                    for ((sink, layer) in triggers.fired) {
                        core.ap.cancellation.checkpoint()
                        if (sink.joinKey != guard.sink.joinKey) continue
                        core.applier.stage(stage.summary, core.ap.zero, Reach.of(layer),
                            Place(ctx.node, statementEdge = false, sources = false)) { premise, result, edge ->
                            core.ap.cancellation.checkpoint()
                            out += planFact(premise, result, stage.kind.identityCandidateOf(edge, null))
                        }
                    }
                } else {
                    for (fact in facts) {
                        core.ap.cancellation.checkpoint()
                        if (guard == Guard.MemoryEffect && !Guard.MemoryEffect.admits(
                                core.config.run1, fact.identityCandidate, fact.facts.layer)) continue
                        val input = fact.facts
                        val place = Place(ctx.node, core.config.run1 && stage.kind.statementEdges,
                            sources = stage.kind == StageKind.SOURCES,
                            site = ResumeSite.CallStageInput(core.operation(ctx.node, ordinal)),
                            callerLayer = ctx.callerLayer, identityCandidate = fact.identityCandidate, pendingDemotion = pendingDemotion)
                        core.applier.stage(stage.summary, fact.premise, input, place) { premise, result, edge ->
                            core.ap.cancellation.checkpoint()
                            out += planFact(premise, result, stage.kind.identityCandidateOf(edge, fact.identityCandidate))
                        }
                    }
                }
                if (stage.trigger != null && out.isNotEmpty()) {
                    core.localServices.fireTriggerSeeds(ctx.node, stage.trigger) { result ->
                        core.ap.cancellation.checkpoint()
                        out += planFact(core.ap.zero, result, null)
                    }
                }
            }
            is CallStage.Actions -> for (fact in facts) {
                core.ap.cancellation.checkpoint()
                cleanChain(stage, fact, ctx, ordinal, pendingDemotion = pendingDemotion) { out += it }
            }
            is CallStage.Callees -> for (fact in facts) {
                core.ap.cancellation.checkpoint()
                enterCallees(ctx, stage, fact)
            }
            is CallStage.Predefined -> for (fact in facts) {
                for (edge in stage.summary.edges) {
                    core.ap.cancellation.checkpoint()
                    if (!RuntimeDataDomain.packet(fact.premise, fact.facts) || !RuntimeDataDomain.producer(edge)) continue
                    core.ops.applyEdge(fact.facts, fact.premise, edge.edge, statementEdge = false,
                        mode = core.mode, out = object : ApOut {
                            override fun result(f: Facts) {
                                if (!RuntimeDataDomain.packet(fact.premise, f)) return
                                if (core.config.run1 && f.base == STATIC) core.routeStaticResultToExit(ctx.node, fact.premise, f)
                                else out += planFact(fact.premise, f, true)
                            }
                            override fun markRequest(mark: TaintMark): Nothing =
                                error("A predefined identity cannot request a mark")
                        }, ruleAssignment = false)
                }
            }
        }
        core.ap.cancellation.checkpoint()
        return out
    }

    private fun cleanChain(actions: CallStage.Actions, fact: PlanFact, ctx: CallContext, stageOrdinal: Int,
                           firstStep: Int = 0, firstPhase: CleanerPhase = CleanerPhase.INPUT,
                           pendingDemotion: Boolean = false, emit: (PlanFact) -> Unit) {
        val core = active()
        val steps = actions.steps
        val schedule = actions.returnGroupSchedule.takeIf {
            core.config.run1 && core.forward && core.mode.markMode == MarkMode.GROUP
        }
        check(schedule == null || schedule.size == steps.size)
        val fullSchedule = actions.returnFullCleanupSchedule.takeIf {
            core.config.run1 && core.forward && core.mode.markMode == MarkMode.FULL &&
                actions.from == CallPoint.RETURNED && actions.to == CallPoint.REWRITTEN
        }
        val node = ctx.node
        fun at(input: PlanFact, step: Int, phase: CleanerPhase) = OperationInput(
            ResumeSite.CleanerInput(core.operation(node, stageOrdinal), step, phase), input.premise, input.facts,
            CallResumeState(ctx.callerLayer, input.identityCandidate, pendingDemotion))
        fun statement(summary: StatementSummary, input: PlanFact, step: Int, phase: CleanerPhase): List<PlanFact> {
            val out = ArrayList<PlanFact>()
            val compiled = if (core.config.run1 && phase == CleanerPhase.READ && summary.staticOperations.isEmpty()) {
                val id = core.operation(node, stageOrdinal).copy(substep = step)
                val operations = summary.edges.filter { it.edge.from.base == STATIC && it.edge.to.base != STATIC }
                    .map { StaticOperation.Read(id, it.forward) }
                if (operations.isEmpty()) summary else summary.withStaticOperations(operations)
            } else if (core.config.run1 && phase == CleanerPhase.WRITE && summary.staticOperations.isEmpty()) {
                val id = core.operation(node, stageOrdinal).copy(substep = step)
                val operations = summary.edges.filter { it.edge.to.base == STATIC && it.edge.from.base != STATIC }
                    .map { StaticOperation.Write(id, Pattern(it.edge.to, ExclusionSet.Empty), it.forward) }
                if (operations.isEmpty()) summary else summary.withStaticOperations(operations)
            } else summary
            core.applier.statement(compiled, input.premise, input.facts,
                Place(node, core.config.run1, sources = false, site = at(input, step, phase).site,
                    callerLayer = ctx.callerLayer, identityCandidate = input.identityCandidate, pendingDemotion = pendingDemotion),
                sink = { premise, result ->
                    core.cut(Cut.STATEMENT, premise, result) { cutPremise, cut ->
                        core.ap.cancellation.checkpoint()
                        out += planFact(cutPremise, cut, input.identityCandidate)
                    }
                }, untouched = { premise, result -> out += planFact(premise, result, input.identityCandidate) })
            return out
        }
        var current = listOf(fact)
        var stepIndex = firstStep
        while (stepIndex < steps.size) {
            core.ap.cancellation.checkpoint()
            if (schedule != null && !schedule.execute(stepIndex, firstStep)) { stepIndex++; continue }
            val block = fullSchedule?.blockContaining(stepIndex)
            if (block != null) {
                val statistics = core.context.shared.n2Statistics
                if (current.all { fullCleanupCollectorFixed(it.premise, it.facts) }) {
                    val mask = block.marksFrom(stepIndex, core.ap.cancellation)
                    statistics?.fullCleanupBlock(stepIndex > block.first, block.end - stepIndex, current.size)
                    val next = PlanFacts(core.ap)
                    for (input in current) {
                        core.ap.cancellation.checkpoint()
                        val address = at(input, stepIndex, CleanerPhase.CLEAN)
                        core.ops.cleanSelectedFullMask(input.facts, input.premise, block.geometry, mask, core.mode,
                            request = { requested ->
                                statistics?.fullCleanupRequested(requested.size)
                                core.needGroups(address, requested)
                            }, out = core.collect(address) { premise, result ->
                                if (result.base == STATIC) core.routeStaticResultToExit(node, premise, result)
                                else next += planFact(premise, result, input.identityCandidate)
                            })
                        if (statistics != null && current.size == 1 && input.facts is FlowTree &&
                            input.facts.base == block.geometry.base) {
                            statistics.fullCleanupSingletonFlow(block.end - stepIndex)
                        }
                    }
                    current = next.toList()
                    stepIndex = block.end
                    continue
                }
                statistics?.fullCleanupFallback()
            }
            val step = steps[stepIndex]
            val phase = if (stepIndex == firstStep) firstPhase else CleanerPhase.INPUT
            // Finish every current-step effect before merging equal inputs to the next step.
            val next: MutableCollection<PlanFact> =
                if (core.config.run1) PlanFacts(core.ap) else ArrayList()
            for (input in current) {
                core.ap.cancellation.checkpoint()
                when (step) {
                    is CleanStep.Clean -> {
                        if (core.config.run1 && step.cleaner.base == STATIC && step.cleaner.mark != null && input.facts is Reach) {
                            val id = core.operation(node, stageOrdinal).copy(substep = stepIndex)
                            val pattern = Pattern(PathFact(STATIC, step.cleaner.pathArray.asList(),
                                if (step.cleaner.reach == CleanReach.EXACT) Tail.EXACT else Tail.ANY,
                                MarkSlot.Concrete(checkNotNull(step.cleaner.mark))), ExclusionSet.Empty)
                            core.reachedOperations(StatementSummary.EMPTY.withStaticOperations(listOf(StaticOperation.MarkInput(id, pattern, includeBase = step.cleaner.reach != CleanReach.BELOW))),
                                at(input, stepIndex, CleanerPhase.CLEAN))
                        }
                        core.ops.clean(input.facts, input.premise, step.cleaner, core.mode,
                        core.collect(at(input, stepIndex, CleanerPhase.CLEAN)) { premise, result ->
                            if (core.config.run1 && result.base == STATIC) {
                                core.routeStaticResultToExit(node, premise, result)
                            } else next += planFact(premise, result, input.identityCandidate)
                        })
                    }
                    is CleanStep.Kill -> core.applier.statement(step.keepEdges, input.premise, input.facts,
                        Place(node, core.config.run1, sources = false, site = at(input, stepIndex, CleanerPhase.INPUT).site,
                            callerLayer = ctx.callerLayer, identityCandidate = input.identityCandidate,
                            pendingDemotion = pendingDemotion),
                        sink = { premise, result -> next += planFact(premise, result, input.identityCandidate) })
                    is CleanStep.Field -> for (read in if (phase == CleanerPhase.CLEAN || phase == CleanerPhase.WRITE) listOf(input)
                            else statement(step.read, input, stepIndex, CleanerPhase.READ)) {
                        core.ap.cancellation.checkpoint()
                        val cleaned: ResultSink = { premise, result ->
                                for (written in statement(step.write, planFact(premise, result, read.identityCandidate), stepIndex, CleanerPhase.WRITE)) {
                                    core.ap.cancellation.checkpoint()
                                    if (written.facts.base != step.temporary) next += written
                                }
                            }
                        if (phase == CleanerPhase.WRITE) cleaned(read.premise, read.facts)
                        else core.ops.clean(read.facts, read.premise, step.cleaner, core.mode,
                            core.collect(at(read, stepIndex, CleanerPhase.CLEAN), cleaned))
                    }
                }
            }
            current = if (core.config.run1) next.toList() else next as ArrayList<PlanFact>
            stepIndex++
        }
        for (result in current) { core.ap.cancellation.checkpoint(); emit(result) }
    }

    private fun observeUnresolved(ctx: CallContext, facts: List<PlanFact>) {
        val core = active()
        val observer = core.context.shared.unresolvedObserver ?: return
        if (ctx.plan.stagesFrom[CallPoint.ADDED].orEmpty().none {
                it is CallStage.Edges && it.kind == StageKind.UNRESOLVED
            }) return
        val observed = checkNotNull(observed)
        for (fact in facts) {
            core.ap.cancellation.checkpoint()
            if (fact.facts !is TaintTree) continue
            val ref = CallerRef(core.key, fact.premise, ctx.callerLayer, ctx.node, scope = core.scope)
            if (observed.add(ref, fact.facts.layer, fact.facts) == null) continue
            observer.reached(ctx.call, fact.facts.base, ctx.plan)
            core.ap.cancellation.checkpoint()
        }
    }

    private fun enterCallees(ctx: CallContext, stage: CallStage.Callees, fact: PlanFact) {
        val core = active()
        val ref = CallerRef(core.key, fact.premise, ctx.callerLayer, ctx.node, ctx.plan.stages.indexOf(stage), core.scope)
        for (callee in stage.callees) {
            core.ap.cancellation.checkpoint()
            val part = Subscription(callee, ref, fact.facts.layer, fact.facts)
            if (!RuntimeDataDomain.packet(ref.premise, fact.facts)) continue
            check(part.added.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter an added link"
            }
            check(part.linkLayer == part.added.layer) { "The link layer must be the added fact's layer" }
            if (core.config.run1) {
                core.runnerPort.subscribe(part)
                core.ap.cancellation.checkpoint()
                core.runnerPort.link(callee, ref, part.linkLayer, part.added)
                continue
            }

            val statistics = core.context.shared.n2Statistics
            statistics?.selectedCallOffered()
            // Saved NORMAL records apply to every offer, without standing input admission.
            replayPersistedSummaries(core.config, core.ops, part, core, statistics)
            if (core.forward) for ((row, member) in core.config.normalTargets.candidates(callee, part, core.mode)) {
                core.ap.cancellation.checkpoint()
                if (!row.premise.isZero) applyTarget(part, row, member, saved = true)
            }
            // Demand admission uses the complete original offer, never a live merge delta.
            val initials = emitRestrictedInitials(core.config, core.ops, callee, part.added, statistics)
            if (initials.isEmpty()) continue

            // Register before a same-unit callee can publish. Current replay remains fresh-only.
            core.runnerPort.subscribe(part)
            core.ap.cancellation.checkpoint()
            // A duplicate live offer can still carry a complete initial packet.
            statistics?.initialPacketOffered(initials.size)
            core.runnerPort.startInitials(callee, initials)
        }
    }

    private fun zeroAtCall(item: EdgeDelta, ctx: CallContext) {
        val core = active()
        if (ctx.plan.zeroCanReturn) core.emitUnchanged(item)
        if (!item.premise.isZero) { check(!core.forward); return }
        if (core.forward) {
            flow(ctx, ctx.plan.entry, listOf(planFact(item.premise, item.facts, null)))
            return
        }
        val seeds = ArrayList<PlanFact>()
        core.localServices.fireSinkSeeds(item.node) { seeds += planFact(core.ap.zero, it, null) }
        if (seeds.isNotEmpty()) flow(ctx, CallPoint.BOUND, seeds)
        val ref = CallerRef(core.key, core.ap.zero, ctx.callerLayer, item.node,
            ctx.plan.stages.indexOfFirst { it is CallStage.Callees }.coerceAtLeast(0), core.scope)
        for (callee in ctx.plan.callees?.callees.orEmpty()) {
            core.ap.cancellation.checkpoint()
            val part = Subscription(callee, ref, item.facts.layer, item.facts, zeroOnly = true)
            val initials = emitRestrictedInitials(core.config, core.ops, callee, part.added)
            if (initials.isEmpty()) continue
            core.runnerPort.subscribe(part)
            core.ap.cancellation.checkpoint()
            core.runnerPort.startInitials(callee, initials)
        }
        for (stage in ctx.plan.stages.filterIsInstance<CallStage.Predefined>()) {
            val results = applyStage(ctx, stage, listOf(planFact(item.premise, item.facts, null)), Triggers.NONE)
            if (results.isNotEmpty()) flow(ctx, stage.to, results)
        }
    }

    override fun applySummary(part: Subscription, pub: Publication, member: Int) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
        if (core.erasesRun1StaticSummary(pub.premise, pub.conclusion)) return
        core.checkPremise(part.ref.premise)
        core.checkPremise(pub.premise)
        when (val premise = pub.premise) {
            is PremiseSet -> ndMatch(part, pub, premise, member)
            is InitialAp -> {
                val results = ArrayList<PlanFact>()
                if (part.zeroOnly) {
                    if (core.config.run1 && pub.conclusion.base == STATIC)
                        core.routeStaticResultToExit(part.ref.call, part.ref.premise, pub.conclusion)
                    else results += planFact(part.ref.premise, pub.conclusion, false)
                }
                else applyParts(part, premise, pub.conclusion, results)
                resumeCallees(part.ref, results)
            }
        }
    }

    override fun applyStaticSummary(part: Subscription, pub: Publication, member: Int) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
        check(core.config.run1 && part.ref.premise.isZero && part.added is Reach && !part.zeroOnly)
        core.checkPremise(pub.premise)
        if (core.erasesRun1StaticSummary(pub.premise, pub.conclusion)) return
        val initial = pub.premise.member(member)
        check(initial.base == STATIC)
        if (core.dropsStaticField(initial)) return
        if (initial.mark is MarkSlot.Star) {
            check(pub.premise is InitialAp && pub.conclusion is FlowTree)
            val value = pub.conclusion.withLayer(Layer.DEMAND)
            resumeCallees(part.ref, listOf(planFact(initial, value, false)))
        } else if (core.hasKnownStaticGroupInput(pub.premise)) {
            val actual = core.knownStaticInput(pub.premise as InitialAp)
            val statistics = core.context.shared.n2Statistics
            for (leaf in core.ops.leaves(pub.conclusion)) {
                core.ap.cancellation.checkpoint()
                statistics?.staticGroupCallOffered()
                statistics?.staticGroupCallDirect()
                val plain = core.ap.factsOf(leaf.fact, leaf.exclusion, pub.layer)
                val scalar = if (plain is TaintTree && pub.conclusion is TaintTree)
                    plain.withProtection(pub.conclusion.nonSubsumable) else plain
                applyStaticInput(part, StaticCallResult.Ap(pub.copy(conclusion = scalar)), member, actual)
            }
        } else core.staticCallInterest(part, StaticCallResult.Ap(pub), member)
    }

    override fun staticSupply(part: Subscription, result: StaticCallResult, member: Int, supply: RegionGroups) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(result.premise)) return
        if (result is StaticCallResult.Ap && core.erasesRun1StaticSummary(result.premise, result.publication.conclusion)) return
        core.checkPremise(part.ref.premise)
        core.checkPremise(result.premise)
        applyStaticInput(part, result, member, core.staticFacts(supply))
    }

    /** Known input and late pool replies share matching and STATIC origin selection. */
    private fun applyStaticInput(part: Subscription, result: StaticCallResult, member: Int, actual: Facts) {
        val core = active()
        val initial = result.premise.member(member)
        val matched = core.ops.satisfying(actual, initial, core.mode) ?: return
        for (leaf in core.ops.leaves(matched)) {
            check(leaf.fact.path.size != 1 || leaf.fact.tail == Tail.EXACT) {
                "A global class-marker call input must remain exact"
            }
            val path = leaf.fact.path.take(2)
            val selected = core.ap.initial(Pattern(leaf.fact.copy(path = path,
                tail = if (leaf.fact.tail == Tail.EXACT && leaf.fact.path.size <= 2) Tail.EXACT else Tail.STAR), ExclusionSet.Empty))
            val ref = part.ref.copy(premise = selected)
            val selectedInput = core.forceRun1Layer(selected, core.ops.startFact(selected, core.mode))
            val input = part.copy(ref = ref, linkLayer = selectedInput.layer, added = selectedInput)
            when (result) {
                is StaticCallResult.Terminal -> applyTarget(input, result.summary, member)
                is StaticCallResult.Ap -> {
                    val pub = result.publication
                    if (pub.premise is PremiseSet) ndMatch(input, pub, pub.premise, member)
                    else {
                        val statistics = core.context.shared.n2Statistics
                        val results = ArrayList<PlanFact>()
                        statistics?.staticGroupScalarApplied()
                        applyParts(input, initial, pub.conclusion, results)
                        if (results.isNotEmpty()) statistics?.staticGroupSuffixEntered()
                        resumeCallees(ref, results)
                    }
                }
            }
        }
    }

    private data class TargetJoinKey(val callee: MethodKey, val premise: PremiseKey, val target: Target,
                                     val call: CommonInst, val stageOrdinal: Int, val saved: Boolean, val scope: BlockScope)
    private data class TargetBinding(val ref: CallerRef, val layer: Layer)
    private val targetJoins = HashMap<TargetJoinKey, KaryJoin<TargetBinding>>()

    override fun applyTarget(part: Subscription, row: TargetSummary, member: Int) =
        applyTarget(part, row, member, saved = false)

    private fun applyTarget(part: Subscription, row: TargetSummary, member: Int, saved: Boolean) {
        val core = active()
        if (!core.forward && row.target is Target.NormalTarget) return
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(row.premise)) return
        val initial = row.premise.member(member)
        if (part.zeroOnly && !initial.isZero) return
        val selected = core.ops.satisfying(part.added, initial, core.mode,
            record = saved && initial.tail != Tail.ANY_TAINT) ?: return
        val layer = if (part.ref.callerLayer == Layer.DEMAND || selected.layer == Layer.DEMAND ||
            part.linkLayer == Layer.DEMAND) Layer.DEMAND else Layer.NORMAL
        if (row.target is Target.NormalTarget && layer != Layer.NORMAL) return
        val binding = TargetBinding(part.ref, layer)
        if (row.premise is InitialAp) emitTargetBinding(listOf(binding), row.target)
        else {
            val key = TargetJoinKey(part.callee, row.premise, row.target, part.ref.call, part.ref.stageOrdinal, saved, part.ref.scope)
            val join = targetJoins.getOrPut(key) { KaryJoin(row.premise.size, core.ap.cancellation) }
            for (bindings in join.add(member, binding)) emitTargetBinding(bindings, row.target)
        }
    }

    private fun emitTargetBinding(bindings: List<TargetBinding>, target: Target) {
        val core = active()
        if (target is Target.NormalTarget && bindings.any { it.layer != Layer.NORMAL }) return
        var premise = core.ap.zero as PremiseKey
        for (binding in bindings) {
            core.ap.cancellation.checkpoint()
            premise = core.ap.union(premise, binding.ref.premise)
        }
        core.emitTarget(premise, target)
    }

    override fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int) {
        val core = active()
        check(core.config.run1 && part.ref.premise.isZero && part.added is Reach && !part.zeroOnly)
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(row.premise)) return
        val initial = row.premise.member(member)
        check(initial.base == STATIC && initial.mark is MarkSlot.Concrete)
        if (core.dropsStaticField(initial)) return
        val result = StaticCallResult.Terminal(row)
        if (core.hasKnownStaticGroupInput(row.premise))
            applyStaticInput(part, result, member, core.knownStaticInput(row.premise as InitialAp))
        else core.staticCallInterest(part, result, member)
    }

    override fun resumePoint(premise: PremiseKey, facts: Facts, site: ResumeSite, state: CallResumeState?) {
        val core = active()
        val node = site.operation.form.statement
        val call = checkNotNull(core.context.callAt(node))
        core.forms.withCall(core.key, node, call) { plan ->
            val ctx = CallContext(node, call, plan, state?.callerLayer ?: facts.layer)
            val stage = checkNotNull(plan.stages.getOrNull(site.operation.stageOrdinal)) { "The resumed call stage changed" }
            val input = planFact(premise, facts, state?.identityCandidate)
            when (site) {
                is ResumeSite.CallStageInput -> {
                    val triggers = if (core.forward && stage.from == CallPoint.BOUND)
                        core.localServices.checkSinksAt(premise, node, facts, plan.sinks,
                            OperationInput(site, premise, facts, state)) else Triggers.NONE
                    val out = applyStage(ctx, stage, listOf(input), triggers, state?.pendingDemotion ?: false)
                    if (out.isNotEmpty()) flow(ctx, stage.to, out, state?.pendingDemotion ?: false)
                }
                is ResumeSite.CleanerInput -> {
                    val actions = checkNotNull(stage as? CallStage.Actions)
                    val out = ArrayList<PlanFact>()
                    cleanChain(actions, input, ctx, site.operation.stageOrdinal, site.step, site.phase,
                        state?.pendingDemotion ?: false) { out += it }
                    if (out.isNotEmpty()) flow(ctx, stage.to, out, state?.pendingDemotion ?: false)
                }
                else -> error("Not a call resume address")
            }
        }
    }

    override fun applyRecord(part: Subscription, record: Record) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(record.premise, record.conclusion)) return
        val premise = record.premise
        val native = ArrayList<PlanFact>()
        val pending = ArrayList<PlanFact>()
        var applied = false
        for (lane in nativeRecordLanes(core.ops, core.mode, part.added, premise)) {
            val results = if (lane.pendingDemotion) pending else native
            applied = applyParts(part.copy(added = lane.actual), premise, record.conclusion, results,
                run1Summary = false) || applied
        }
        if (applied) core.countRecordCrossing()
        resumeCallees(part.ref, native)
        val tagged = ArrayList<PlanFact>(pending.size)
        for (fact in pending) { core.ap.cancellation.checkpoint(); tagged += planFact(fact.premise, fact.facts, false) }
        resumeCallees(part.ref, tagged, pendingDemotion = true)
    }

    override fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.base(view.premise.fact.base) || !RuntimeDataDomain.base(view.result.fact.base)) return
        val results = ArrayList<PlanFact>()
        var applied = false
        val identity = recordLeafIdentity(view)
        core.ops.applyRecordLeaf(part.added, view, nonSubsumable, core.mode, core.collect(part.ref.premise, part.added) { premise, result ->
            applied = true
            if (!completeBackwardSource(view.premise.fact.base == AccessPathBase.Zero, premise, result))
                results += planFact(premise, result, identity)
        }, original = part.ref.premise)
        if (applied) core.countRecordCrossing()
        resumeCallees(part.ref, results)
    }

    /** Source discharge is terminal. ZERO-to-ZERO remains ordinary control flow. */
    private fun completeBackwardSource(zeroPremise: Boolean, original: PremiseKey, result: Facts): Boolean {
        val core = active()
        if (core.forward || zeroPremise || result !is Reach) return false
        core.emitTarget(original, Target.DemandTarget)
        return true
    }

    private fun toDemand(facts: Facts): Facts {
        val core = active()
        return when (facts) {
            is TaintTree -> facts.withLayer(Layer.DEMAND)
            is Reach -> Reach.DEMAND
            is FlowTree -> error("A must record has TAINT results")
        }
    }

    private fun resumeCallees(ref: CallerRef, results: List<PlanFact>, pendingDemotion: Boolean = false) {
        val core = active()
        if (results.isEmpty()) return
        val call = checkNotNull(core.context.callAt(ref.call)) { "The caller reference is not at a call" }
        core.forms.withCall(core.key, ref.call, call) { plan ->
            val ctx = CallContext(ref.call, call, plan, ref.callerLayer)
            val stage = ctx.plan.stages.getOrNull(ref.stageOrdinal) as? CallStage.Callees
                ?: checkNotNull(ctx.plan.callees) { "A resumed result needs a callee stage" }
            flow(ctx, stage.to, results, pendingDemotion)
        }
    }

    private fun applyParts(part: Subscription, premise: InitialAp, conclusion: Facts, results: MutableList<PlanFact>,
                           run1Summary: Boolean = true): Boolean {
        val core = active()
        var applied = false
        for ((group, identity) in summaryParts(premise, conclusion, run1Summary)) {
            core.ap.cancellation.checkpoint()
            val at = OperationInput(ResumeSite.CallStageInput(core.operation(part.ref.call, part.ref.stageOrdinal)),
                part.ref.premise, part.added, CallResumeState(part.ref.callerLayer, identity))
            core.ops.applySummary(part.added, premise, group, core.mode, core.collect(at) { pr, result ->
                applied = true
                if (!completeBackwardSource(premise.isZero, pr, result)) {
                    if (core.config.run1 && result.base == STATIC) core.routeStaticResultToExit(part.ref.call, pr, result)
                    else results += planFact(pr, result, identity)
                }
            }, original = part.ref.premise)
        }
        return applied
    }

    private fun summaryParts(premise: InitialAp, conclusion: Facts, run1Summary: Boolean): List<Pair<Facts, Boolean>> {
        val core = active()
        if (core.config.run1 && run1Summary) return core.ap.run1SummaryParts(premise, conclusion)
        val start = core.ops.startFact(premise)
        if (premise.isZero || conclusion.layer != Layer.NORMAL || conclusion.groupKey != start.groupKey)
            return listOf(conclusion to false)
        val effect = core.ops.without(conclusion, start)
        val identity = if (effect == null) conclusion else core.ops.without(conclusion, effect)
        return listOfNotNull(effect?.let { it to false }, identity?.let { it to true })
    }

    private fun ndMatch(part: Subscription, pub: Publication, premise: PremiseSet, member: Int) {
        val core = active()
        check(core.forward && !core.config.run1) { "Conjunctive summaries require a later forward run" }
        check(!part.zeroOnly && part.added !is Reach && !premise.member(member).isZero)
        val conclusion = checkNotNull(pub.conclusion as? TaintTree) { "A multi-premise publication is TAINT" }
        val matched = matches(part, pub, member, core.ops, core.mode) ?: return
        check(matched is TaintTree) { "An E6 member input is TAINT" }
        check(part.linkLayer == matched.layer) { "The matched fact and link have the same layer" }
        val store = checkNotNull(core.localServices.conjunctions) { "Forward calls need their local conjunction store" }
        val join = store.ndJoin<NdBinding>(ConjunctionStore.NdKey(part.callee, premise, pub.layer, part.ref.call, part.ref.stageOrdinal, part.ref.scope))
        val binding = NdBinding(part.ref, matched.layer).also {
            it.triggering = (premise.member(member).mark as? MarkSlot.Concrete)?.mark
                ?.let { mark -> core.ap.marks.runtimeAtom(mark, core.mode.markMode) }
            it.nonSubsumable = matched.nonSubsumable != null
        }
        val fresh = join.addSubscription(member, binding) { previous, offered ->
            check(previous.triggering == offered.triggering)
            val changed = offered.nonSubsumable && !previous.nonSubsumable
            previous.nonSubsumable = previous.nonSubsumable || offered.nonSubsumable
            changed
        }
        for ((parts, result) in fresh) {
            core.ap.cancellation.checkpoint()
            applyCombination(parts, result)
        }
        for ((parts, result) in join.addConclusion(conclusion)) {
            core.ap.cancellation.checkpoint()
            applyCombination(parts, result)
        }
    }

    private fun applyCombination(parts: List<NdBinding>, conclusion: TaintTree) {
        val core = active()
        var union = parts[0].ref.premise
        val layers = ArrayList<Layer>(parts.size)
        for (index in parts.indices) {
            core.ap.cancellation.checkpoint()
            if (index != 0) union = core.ap.union(union, parts[index].ref.premise)
            layers += parts[index].linkLayer
        }
        val ref = parts.first().ref
        val results = ArrayList<PlanFact>()
        val at = OperationInput(ResumeSite.CallStageInput(core.operation(ref.call, ref.stageOrdinal)), union, conclusion,
            CallResumeState(ref.callerLayer))
        core.ops.applyMatchedCombination(layers, conclusion, core.collect(at) { pr, result ->
            val inherited = parts.any { it.nonSubsumable }
            var protected = if (inherited && result is TaintTree) result.withProtection(result.root) else result
            if (protected is TaintTree) {
                val restored = MarkSet(union.members.mapNotNull { (it.mark as? MarkSlot.Concrete)?.mark }
                    .map { core.ap.marks.runtimeAtom(it, core.mode.markMode) }
                    .filter { origin -> parts.any { it.triggering != null && it.triggering != origin } }
                    .map { it.id }.toIntArray())
                protected = core.ap.selectedProtection(protected, restored)
            }
            if (core.config.run1 && protected.base == STATIC) core.routeStaticResultToExit(ref.call, pr, protected)
            else results += planFact(pr, protected, false)
        })
        resumeCallees(ref, results)
    }

    override fun freeze() {
        targetJoins.clear()
        observed = null
        owner = null
    }
}

/** Header-only gate. NORMAL ZERO-origin exact source leaves are collector-fixed too.
 * Keep NORMAL MUST/STAR on the scalar path: repeated partial cleaning can add
 * redundant raw DEMAND exact rows, so it does not have the same raw callback image. */
internal fun fullCleanupCollectorFixed(premise: PremiseKey, facts: Facts): Boolean {
    if (facts is FlowTree && facts.exclusion != ExclusionSet.Empty) return false
    if (facts is TaintTree && (facts.exclusion != ExclusionSet.Empty ||
            facts.layer != Layer.DEMAND && (!premise.isZero || facts.root.hasAny))) return false
    if ((facts.base == STATIC || Run1StaticService.hasStaticMember(premise)) && facts.layer != Layer.DEMAND) return false
    return true
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import java.util.IdentityHashMap
import org.opentaint.dataflow.graph.PortId

/** One admitted relation. Outgoing demand is a filtered view of the final stored headers. */
class RunSummaryStore(private val m: ApManager, flowBacked: Boolean = false) {
    private val groups = IdentityHashMap<PremiseKey, ConclusionGroup>()
    private val interners = m.newInterners()
    private val backed = if (flowBacked) FlowBackedSummaries(m) else null

    /** Add a candidate only after the actor has completed demand restriction. */
    fun addAdmitted(premise: PremiseKey, g: Facts): Facts? {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, g)) return null
        checkShape(premise, g)
        backed?.let { return it.add(premise, g) }
        return groups.getOrPut(premise) { ConclusionGroup(m, interners) }.add(g)
    }

    fun all(): Sequence<Pair<PremiseKey, Facts>> = backed?.all() ?: entries(groups)

    fun demandEdges(direction: Direction): Sequence<Pair<PremiseKey, Facts>> =
        all().filter { (premise, facts) -> selectedForHandoff(premise, facts.layer, direction) }

    fun census(): RelationCensus = census { _, _ -> true }

    fun demandCensus(direction: Direction): RelationCensus =
        census { premise, layer -> selectedForHandoff(premise, layer, direction) }

    private fun census(include: (PremiseKey, Layer) -> Boolean): RelationCensus {
        m.cancellation.checkpoint()
        backed?.let { return it.census(include) }
        val counter = RelationCensusCounter(m.cancellation)
        var result = RelationCensus.ZERO
        for ((premise, group) in groups) for (facts in group.all()) {
            m.cancellation.checkpoint()
            if (include(premise, facts.layer)) result += counter.scalar(facts)
        }
        return result
    }

    /** Borrow the current admitted relation on its actor owner. Consume this view
     * before mutating the store; do not retain a historical Facts snapshot. */
    fun borrow(premise: PremiseKey): Sequence<Facts> {
        m.cancellation.checkpoint()
        return backed?.borrow(premise) ?: groups[premise]?.all() ?: emptySequence()
    }

    private fun checkShape(premise: PremiseKey, facts: Facts) {
        assertCanonicalFlowSummary(premise, facts)
        check(facts.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter a summary" }
        check((facts is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the premise" }
        check(premise !is PremiseSet || facts is TaintTree) { "A multi-premise summary must be TAINT" }
    }

    private fun entries(source: IdentityHashMap<PremiseKey, ConclusionGroup>): Sequence<Pair<PremiseKey, Facts>> = sequence {
        m.cancellation.checkpoint()
        for ((premise, group) in source) {
            m.cancellation.checkpoint()
            for (facts in group.all()) {
                m.cancellation.checkpoint()
                yield(premise to facts)
            }
        }
    }
}

/** Allocate only exits which actually publish a completed traversal. The owner
 * keeps one instance per entry scope; AP admission remains RunSummaryStore's law. */
class PortSummaryStores(private val m: ApManager, private val flowBacked: Boolean = false) {
    private val byExit = LinkedHashMap<PortId, RunSummaryStore>()

    fun at(exit: PortId): RunSummaryStore {
        m.cancellation.checkpoint()
        return byExit.getOrPut(exit) { RunSummaryStore(m, flowBacked) }
    }

    fun existing(exit: PortId): RunSummaryStore? = byExit[exit]

    /** Borrow only on the method owner; a frozen handoff must copy admitted rows. */
    fun entries(): Sequence<Pair<PortId, RunSummaryStore>> = sequence {
        for ((exit, rows) in byExit) {
            m.cancellation.checkpoint()
            yield(exit to rows)
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.PortId
import org.opentaint.dataflow.graph.BlockId

/** An admitted normal singleton summary, retained in the direction in which it was derived. */
class Record(
    val method: MethodKey,
    val direction: Direction,
    val premise: InitialAp,
    val conclusion: Facts,
    val scope: BlockScope? = null,
    val exit: PortId? = null,
) {
    init { require((scope == null) == (exit == null)) { "A scoped native record keeps both control ports" } }

    /** AP reversal is below; reverse the control ports independently. */
    fun scopeIn(direction: Direction): BlockScope? = scope?.let {
        if (direction == this.direction) it else BlockScope(it.block, checkNotNull(exit))
    }
    fun exitIn(direction: Direction): PortId? = scope?.let {
        if (direction == this.direction) exit else it.entry
    }
    /** Transient opposite-direction reads retain their actual premise and result layer. */
    private fun reversedLeavesAt(a: Pattern): Sequence<Pair<RecordLeafView, Boolean>> = sequence {
        val m = premise.manager
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, conclusion) || !RuntimeDataDomain.base(a.fact.base)) return@sequence
        check(conclusion.layer == Layer.NORMAL) { "Only a normal native record has reversed views" }
        val nativePremise = premise.toPattern()
        for (leaf in ApOps(m).leaves(conclusion)) {
            m.cancellation.checkpoint()
            if (leaf.fact.base != a.fact.base ||
                !(leaf.fact.path.startsWith(a.fact.path) || a.fact.path.startsWith(leaf.fact.path))) continue
            reverseOne(leaf, nativePremise)?.let { yield(it) }
        }
    }

    /** Metadata is an invocation annotation, not part of RecordLeafView equality. */
    fun forEachReversedAt(a: Pattern, emit: (RecordLeafView, Boolean) -> Unit) {
        for ((view, nonSubsumable) in reversedLeavesAt(a)) emit(view, nonSubsumable)
    }

    /** Read-only geometry view for diagnostic and reference clients. */
    fun reversedAt(a: Pattern): Sequence<RecordLeafView> = reversedLeavesAt(a).map { it.first }

    internal fun reverseOne(leaf: Pattern, nativePremise: Pattern): Pair<RecordLeafView, Boolean>? {
        val m = premise.manager
        val view = reverseRecordLeaf(direction, nativePremise, Conclusion(leaf.fact, leaf.exclusion, demand = false))
            ?: return null
        var at: TaintNode? = (conclusion as? TaintTree)?.nonSubsumable
        for (accessor in leaf.fact.path) { m.cancellation.checkpoint(); at = at?.child(accessor) }
        val atom = (leaf.fact.mark as? MarkSlot.Concrete)?.mark
        val protected = atom != null && at?.leaf?.let {
            atom in if (leaf.fact.tail == Tail.EXACT) it.exact else it.any
        } == true
        return view to protected
    }
}

/** One actual output position, not a full-mark posting. Record identity is unchanged. */
class RecordOutputPosition internal constructor(val record: Record, private val node: PathNode?, val ordinal: Int) {
    val path: List<Int> get() = node?.toList() ?: emptyList()
    fun forEachReversedAt(actual: Pattern, emit: (RecordLeafView, Boolean) -> Unit) {
        val m = record.premise.manager
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(record.premise, record.conclusion) || actual.fact.base != record.conclusion.base) return
        val p = path
        if (!(p.startsWith(actual.fact.path) || actual.fact.path.startsWith(p))) return
        check(record.conclusion.layer == Layer.NORMAL)
        val nativePremise = record.premise.toPattern()
        fun offer(pattern: Pattern) { record.reverseOne(pattern, nativePremise)?.let { (view, protected) -> emit(view, protected) } }
        when (val value = record.conclusion) {
            is Reach -> if (p.isEmpty()) offer(m.zero.toPattern())
            is FlowTree -> {
                var at: FlowNode? = value.root
                for (accessor in p) { m.cancellation.checkpoint(); at = at?.child(accessor) }
                if (at?.leaf?.isEmpty == false)
                    offer(Pattern(PathFact(value.base, p, value.tail, MarkSlot.Star(value.markExclusion)), value.exclusion))
            }
            is TaintTree -> {
                var at: TaintNode? = value.root
                for (accessor in p) { m.cancellation.checkpoint(); at = at?.child(accessor) }
                val leaf = at?.leaf ?: return
                for (id in leaf.exact.data) {
                    m.cancellation.checkpoint()
                    offer(Pattern(PathFact(value.base, p, Tail.EXACT, MarkSlot.Concrete(TaintMark(id))), ExclusionSet.Empty))
                }
                for (id in leaf.any.data) {
                    m.cancellation.checkpoint()
                    offer(Pattern(PathFact(value.base, p, value.anyTail, MarkSlot.Concrete(TaintMark(id))), value.exclusion))
                }
            }
        }
    }
    override fun equals(other: Any?): Boolean = other is RecordOutputPosition && record === other.record && ordinal == other.ordinal
    override fun hashCode(): Int = 31 * System.identityHashCode(record) + ordinal
}

/** Persistent native records. A run obtains a view that permits reads only. */
interface RecordStore {
    fun add(record: Record)
    fun byEntry(method: MethodKey, addedFact: Pattern): Sequence<Record>
    fun byExit(method: MethodKey, fact: Pattern): Sequence<Record>
    fun byEntry(method: MethodKey, scope: BlockScope, addedFact: Pattern): Sequence<Record> = emptySequence()
    fun byExit(method: MethodKey, scope: BlockScope, fact: Pattern): Sequence<Record> = emptySequence()
    fun byExitPositions(method: MethodKey, scope: BlockScope, fact: Pattern): List<RecordOutputPosition>? = null
    fun view(): RecordStore
    fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>)
    fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>) {
        check(!summaries.iterator().hasNext()) { "This record store does not support scoped persistence" }
    }
}

data class ScopedRunSummary(val key: ScopedSummaryKey, val summaries: RunSummaryStore)

/** The driver writes only at a barrier; the next run reads the published indexes. */
class PersistentRecordStore(private val m: ApManager) : RecordStore {
    private val entry = HashMap<MethodKey, PathTrie<Record>>()
    private val exit = HashMap<MethodKey, PathTrie<RecordOutputPosition>>()
    private data class ScopedIndexKey(val method: MethodKey, val block: BlockId, val port: PortId)
    private data class MergeKey(val method: MethodKey, val direction: Direction, val premise: InitialAp,
                                val scope: BlockScope?, val exit: PortId?)
    private val scopedEntry = HashMap<ScopedIndexKey, PathTrie<Record>>()
    private val scopedExit = HashMap<ScopedIndexKey, PathTrie<RecordOutputPosition>>()
    private val merged = HashMap<MergeKey, ConclusionGroup>()
    private val interners = m.newInterners()

    override fun add(record: Record) {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(record.premise, record.conclusion)) return
        checkNativeRecord(record.direction, record.premise, record.conclusion)
        val input = if (record.scope == null) entry.getOrPut(record.method) { PathTrie(m.cancellation) }
            else scopedEntry.getOrPut(ScopedIndexKey(record.method, record.scope.block, record.scope.entry)) {
                PathTrie(m.cancellation)
            }
        input.add(record.premise.base, record.premise.pathArray, record)
        val output = if (record.scope == null) exit.getOrPut(record.method) { PathTrie(m.cancellation) }
            else scopedExit.getOrPut(ScopedIndexKey(record.method, record.scope.block, checkNotNull(record.exit))) {
                PathTrie(m.cancellation)
            }
        var ordinal = 0
        m.forEachLeafPosition(record.conclusion) { base, path ->
            output.add(base, path, RecordOutputPosition(record, m.path(path.asList()), ordinal++))
        }
    }

    /** R2 candidates; the caller tests applicable or inside on the full native premise. */
    override fun byEntry(method: MethodKey, addedFact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(addedFact.fact.base)) return@sequence
        val candidates = entry[method]?.around(addedFact.fact.base, addedFact.fact.path.toIntArray()).orEmpty()
        for (record in candidates) {
            m.cancellation.checkpoint()
            yield(record)
        }
    }

    /** A record at several exit leaf positions is returned once. R3 supplies its transient views. */
    override fun byExit(method: MethodKey, fact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return@sequence
        val candidates = exit[method]?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()
        val seen = HashSet<Record>()
        for (position in candidates) {
            m.cancellation.checkpoint()
            if (seen.add(position.record)) yield(position.record)
        }
    }

    override fun byEntry(method: MethodKey, scope: BlockScope, addedFact: Pattern): Sequence<Record> =
        scopedCandidates(scopedEntry[ScopedIndexKey(method, scope.block, scope.entry)], addedFact)

    override fun byExit(method: MethodKey, scope: BlockScope, fact: Pattern): Sequence<Record> =
        sequence {
            val seen = HashSet<Record>()
            for (position in byExitPositions(method, scope, fact)) if (seen.add(position.record)) yield(position.record)
        }

    override fun byExitPositions(method: MethodKey, scope: BlockScope, fact: Pattern): List<RecordOutputPosition> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return emptyList()
        return scopedExit[ScopedIndexKey(method, scope.block, scope.entry)]
            ?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()
    }

    private fun scopedCandidates(index: PathTrie<Record>?, fact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return@sequence
        val seen = HashSet<Record>()
        for (record in index?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()) {
            m.cancellation.checkpoint()
            if (seen.add(record)) yield(record)
        }
    }

    override fun view(): RecordStore = object : RecordStore by this {
        override fun add(record: Record) = error("Read-only during a run (analyzer-core.md A4)")
        override fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>) =
            error("Read-only during a run (analyzer-core.md A4)")
        override fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>): Unit =
            error("Read-only during a run (analyzer-core.md A4)")
        override fun view(): RecordStore = this
    }

    /** R1 reads admitted summaries, merges eligible native values and indexes their propagation delta. */
    override fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>) {
        for ((method, store) in summaries) persistOne(direction, method, null, null, store)
    }

    override fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>) {
        for ((key, store) in summaries)
            persistOne(direction, key.method, key.scope, key.exit, store)
    }

    private fun persistOne(direction: Direction, method: MethodKey, scope: BlockScope?, exit: PortId?,
                           store: RunSummaryStore) {
        m.cancellation.checkpoint()
        for ((premise, facts) in store.all()) {
            m.cancellation.checkpoint()
            if (!RuntimeDataDomain.packet(premise, facts) || facts.layer == Layer.DEMAND) continue
            val initial = premise as? InitialAp ?: continue
            if (direction == Direction.BACKWARD && initial.isZero) continue
            checkNativeRecord(direction, initial, facts)
            val delta = merged.getOrPut(MergeKey(method, direction, initial, scope, exit)) {
                ConclusionGroup(m, interners)
            }.add(facts) ?: continue
            add(Record(method, direction, initial, delta, scope, exit))
        }
    }
}

private fun checkNativeRecord(direction: Direction, premise: InitialAp, conclusion: Facts) {
    assertCanonicalFlowSummary(premise, conclusion)
    check(conclusion.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter a native record" }
    check(conclusion.layer == Layer.NORMAL) { "R1: a native record must be normal" }
    check((conclusion is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the native premise" }
    check(premise.isZero || when (premise.mark) {
        is MarkSlot.Concrete -> premise.tail != Tail.STAR
        is MarkSlot.Star -> premise.tail == Tail.STAR || premise.tail == Tail.ANY_TAINT
    }) { "A native record needs a zero, concrete exact/any or abstract STAR initial" }
    if (direction == Direction.BACKWARD) {
        check(!premise.isZero) { "R1: a backward zero-premise edge is not a native record" }
        check(premise.tail != Tail.ANY_TAINT) { "W8 (d): a backward record cannot have a must premise" }
        check(conclusion !is TaintTree || !conclusion.root.hasAny) { "W6: a backward any leaf is demand" }
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.SoftReferenceManager

/** FLOW values for one base, separated by layer and both exclusions. One store writer owns this group. */
class FlowGroup(private val m: ApManager, private val interner: TrieInterner<FlowLeaf>) {
    private val trees = arrayOf(ArrayList<FlowTree>(1), ArrayList<FlowTree>(1))

    fun all(): Sequence<FlowTree> = trees[0].asSequence() + trees[1].asSequence()

    /** T4: return the new part, or the merged value when T2 changes an annotation. */
    fun add(t: FlowTree): FlowTree? {
        val list = trees[t.layer.ordinal]
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.exclusion == pending.exclusion && it.markExclusion == pending.markExclusion
            }
            if (i >= 0) {
                val rest = subtractSubsumed(pending, list) ?: return null
                val (merged, delta) = FlowAlgebra.mergeAddDelta(list[i].root, rest.root, m.cancellation)
                if (delta == null) return null
                list[i] = list[i].withRoot(interner.internIfRequired(merged))
                return m.flowTree(pending.base, pending.layer, pending.exclusion, pending.markExclusion, delta, pending.tail)
            }

            val k = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.root == pending.root &&
                    (it.markExclusion == pending.markExclusion || it.exclusion == pending.exclusion)
            }
            if (k >= 0) {
                val stored = list[k]
                val merged = m.flowTree(pending.base, pending.layer,
                    stored.exclusion.intersect(pending.exclusion),
                    stored.markExclusion.intersect(pending.markExclusion), stored.root, pending.tail)
                if (merged.exclusion == stored.exclusion && merged.markExclusion == stored.markExclusion) return null
                list.removeAt(k)
                pending = merged
                continue
            }

            val fresh = subtractSubsumed(pending, list) ?: return null
            list += fresh.withRoot(interner.internIfRequired(fresh.root))
            return fresh
        }
    }

    private fun subtractSubsumed(t: FlowTree, others: List<FlowTree>): FlowTree? {
        var root = t.root
        for (stored in others) {
            m.cancellation.checkpoint()
            val marks = stored.markExclusion.isSubsetOf(t.markExclusion)
            val atOk = marks && when (stored.tail) {
                Tail.ANY -> true
                Tail.STAR -> t.tail == Tail.STAR && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.EXACT -> t.tail == Tail.EXACT && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.ANY_TAINT -> t.tail == Tail.ANY_TAINT && stored.exclusion.isSubsetOf(t.exclusion)
            }
            val belowOk = marks && stored.tail == Tail.ANY
            root = FlowAlgebra.subtract(root, stored.root, FlowLeaf.NONE,
                at = { if (atOk) it else FlowLeaf.NONE },
                below = { if (belowOk) it else FlowLeaf.NONE },
                cancellation = m.cancellation) ?: return null
        }
        return if (root === t.root) t else t.withRoot(root)
    }
}

/** Construct a store result after its mask is proved to be included in root.
 * This is coordinate inclusion, not AP prefix coverage. General factories still trim. */
private fun admittedTree(
    m: ApManager, header: TaintTree, root: TaintNode, includedMask: TaintNode?,
    exclusion: ExclusionSet = header.exclusion,
): TaintTree = TaintTree(
    header.base, header.layer, root,
    if (!root.hasAny || header.anyTail == Tail.ANY) ExclusionSet.Empty else m.intern(exclusion),
    if (root.hasAny) header.anyTail else Tail.ANY_TAINT,
    includedMask,
)

/** TAINT values for one base. STAR and must spans keep distinct suffix semantics. */
class TaintGroup(private val m: ApManager, private val interner: TrieInterner<TaintLeaves>) {
    private val trees = arrayOf(ArrayList<TaintTree>(1), ArrayList<TaintTree>(1))

    fun all(): Sequence<TaintTree> = trees[0].asSequence() + trees[1].asSequence()

    /** Restore one complete current typed header for a temporary admission
     * adapter. Do not re-admit the snapshot: that would compact old STAR rows
     * merely because a later ANY row is already present. No history is kept. */
    internal fun restoreCurrent(t: TaintTree) {
        m.cancellation.checkpoint()
        val list = trees[t.layer.ordinal]
        check(list.none { it.anyTail == t.anyTail && it.exclusion == t.exclusion })
        list += t
    }

    fun add(t: TaintTree): TaintTree? {
        val alg = m.taintAlg
        val list = trees[t.layer.ordinal]
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val sameKey = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == pending.anyTail && it.exclusion == pending.exclusion
            }
            if (sameKey < 0) {
                val k = list.indexOfFirst {
                    m.cancellation.checkpoint()
                    it.anyTail == pending.anyTail && it.root == pending.root
                }
                if (k >= 0) {
                    val stored = list[k]
                    val exclusion = stored.exclusion.intersect(pending.exclusion)
                    // Equal ordinary content can still carry a new protected membership.
                    if (exclusion == stored.exclusion) {
                        val rest = subtractSubsumed(pending, list) ?: return null
                        val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
                        val root = alg.mergeAdd(stored.root, rest.root, m.cancellation)
                        list[k] = admittedTree(m, stored, interner.internIfRequired(root), protection)
                        return rest
                    }
                    list.removeAt(k)
                    pending = admittedTree(m, pending, stored.root,
                        mergeProtection(stored.nonSubsumable, pending.nonSubsumable), exclusion)
                    continue
                }
            }

            val rest = subtractSubsumed(pending, list) ?: return null
            // Subtraction can remove the last must leaf. Its canonical key is then Empty E.
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == rest.anyTail && it.exclusion == rest.exclusion
            }
            if (i < 0) {
                list += admittedTree(m, rest, interner.internIfRequired(rest.root), rest.nonSubsumable)
                return rest
            }
            val stored = list[i]
            val (merged, delta) = alg.mergeAddDelta(stored.root, rest.root, m.cancellation)
            val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
            val deltaRoot = mergeProtection(delta, rest.nonSubsumable) ?: return null
            list[i] = admittedTree(m, stored, interner.internIfRequired(merged), protection)
            return admittedTree(m, rest, deltaRoot, rest.nonSubsumable)
        }
    }

    private fun subtractSubsumed(t: TaintTree, others: List<TaintTree>): TaintTree? {
        val ordinary = subtract(t.root, t, others, protectedOnly = false)
        // Ordinary ANY coverage cannot consume a fresh protected EXACT dependency.
        val protection = t.nonSubsumable?.let { subtract(it, t, others, protectedOnly = true) }
        val root = mergeProtection(ordinary, protection) ?: return null
        if (root === t.root && protection === t.nonSubsumable) return t
        return admittedTree(m, t, root, protection)
    }

    private fun mergeProtection(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> m.taintAlg.mergeAdd(a, b, m.cancellation)
    }

    private fun subtract(root: TaintNode, t: TaintTree, others: List<TaintTree>,
                         protectedOnly: Boolean): TaintNode? {
        val alg = m.taintAlg
        var remaining = root
        for (stored in others) {
            m.cancellation.checkpoint()
            val storedRoot = if (protectedOnly) stored.nonSubsumable ?: continue else stored.root
            val storedMay = stored.anyTail == Tail.ANY
            val storedStar = stored.anyTail == Tail.STAR
            val coversAny = storedMay || stored.anyTail == t.anyTail
            val anyAt = coversAny && (storedMay || stored.exclusion.isSubsetOf(t.exclusion))
            remaining = alg.subtract(remaining, storedRoot, TaintLeaves.EMPTY,
                at = { alg.leaves(if (storedMay) it.exact + it.any else it.exact,
                    if (anyAt) it.any else MarkSet.EMPTY) },
                below = { alg.leaves(if (storedMay) it.any else MarkSet.EMPTY,
                    if (coversAny && !storedStar) it.any else MarkSet.EMPTY) },
                admits = stored.exclusion::admits,
                cancellation = m.cancellation) ?: return null
        }
        return remaining
    }
}

/** All conclusion bases and kinds for one premise key. REACH has one bit per layer. */
class ConclusionGroup(private val m: ApManager, private val interners: StoreInterners) {
    private val reach = BooleanArray(2)
    private val flow = HashMap<AccessPathBase, FlowGroup>(2)
    private val taint = HashMap<AccessPathBase, TaintGroup>(2)

    fun add(f: Facts): Facts? {
        m.cancellation.checkpoint()
        return when (f) {
            is Reach -> if (reach[f.layer.ordinal]) null else f.also { reach[f.layer.ordinal] = true }
            is FlowTree -> flow.getOrPut(f.base) { FlowGroup(m, interners.flow) }.add(f)
            is TaintTree -> taint.getOrPut(f.base) { TaintGroup(m, interners.taint) }.add(f)
        }
    }

    fun all(): Sequence<Facts> = Layer.entries.asSequence().filter { reach[it.ordinal] }.map(Reach::of) +
        flow.values.asSequence().flatMap { it.all() } + taint.values.asSequence().flatMap { it.all() }
}

/** Soft trie caches for one store, with a separate table for each leaf kind. */
class StoreInterners(refs: SoftReferenceManager, private val cancellation: Cancellation) {
    val flow = TrieInterner<FlowLeaf>(refs, cancellation)
    val taint = TrieInterner<TaintLeaves>(refs, cancellation)

    fun internIfRequired(f: Facts): Facts {
        cancellation.checkpoint()
        return when (f) {
            is Reach -> f
            is FlowTree -> flow.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
            is TaintTree -> taint.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
        }
    }
}
